import { UriTemplateError, parse } from './parse.js';

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  if (!variables || typeof variables !== 'object') {
    throw new UriTemplateError('variables must be an object');
  }

  const parts = parse(template);
  let result = '';

  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeLiteral(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }

  return result;
}

const UNRESERVED = /[a-zA-Z0-9\-._~]/;
const RESERVED = /[:/?#\[\]@!$&'()*+,;=]/;

function encodeLiteral(text) {
  let result = '';
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    // Check if it's a percent-triplet
    if (char === '%' && i + 2 < text.length && /[0-9A-Fa-f]{2}/.test(text.slice(i + 1, i + 3))) {
      result += text.slice(i, i + 3);
      i += 2;
    } else if (UNRESERVED.test(char) || RESERVED.test(char)) {
      result += char;
    } else {
      result += encodeUtf8(char);
    }
  }
  return result;
}

function encodeUtf8(char) {
  const encoded = Buffer.from(char, 'utf-8');
  let result = '';
  for (let i = 0; i < encoded.length; i++) {
    result += '%' + encoded[i].toString(16).toUpperCase().padStart(2, '0');
  }
  return result;
}

function encodeValue(text, isReserved) {
  let result = '';
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    // Check if it's a percent-triplet
    if (char === '%' && i + 2 < text.length && /[0-9A-Fa-f]{2}/.test(text.slice(i + 1, i + 3))) {
      if (isReserved) {
        result += text.slice(i, i + 3);
      } else {
        // Re-encode the percent sign
        result += '%25' + text.slice(i + 1, i + 3);
      }
      i += 2;
    } else if (UNRESERVED.test(char)) {
      result += char;
    } else if (isReserved && RESERVED.test(char)) {
      result += char;
    } else {
      result += encodeUtf8(char);
    }
  }
  return result;
}

function expandExpression(expr, variables) {
  const { operator, variables: vars } = expr;

  // Operator table: [prefix, separator, named, emptyValue]
  const operatorTable = {
    '': ['', ',', false, ''],
    '+': ['', ',', false, ''],
    '#': ['#', ',', false, ''],
    '.': ['.', '.', false, ''],
    '/': ['/', '/', false, ''],
    ';': [';', ';', true, ''],
    '?': ['?', '&', true, '='],
    '&': ['&', '&', true, '=']
  };

  const [prefix, separator, named, emptyValue] = operatorTable[operator];
  const isReserved = operator === '+' || operator === '#';

  const pieces = [];

  for (const varSpec of vars) {
    const value = variables[varSpec.name];

    // Skip absent, null, undefined values
    if (value === null || value === undefined || !Object.prototype.hasOwnProperty.call(variables, varSpec.name)) {
      continue;
    }

    // Expand the variable
    const varPieces = expandVariable(varSpec, value, isReserved);
    if (varPieces.length > 0) {
      if (!varSpec.explode && (Array.isArray(value) || (typeof value === 'object' && value !== null && !(value instanceof Array)))) {
        // Non-exploded composite: join all parts with separator
        if (named) {
          pieces.push(`${varSpec.name}=${varPieces.join(',')}`);
        } else {
          pieces.push(varPieces.join(','));
        }
      } else if (varSpec.explode && Array.isArray(value)) {
        // Exploded array
        for (const item of value) {
          if (item === null || item === undefined) continue;
          const encoded = encodeValue(String(item), isReserved);
          pieces.push(`${varSpec.name}=${encoded}`);
        }
      } else if (varSpec.explode && typeof value === 'object' && value !== null) {
        // Exploded object
        for (const [k, v] of Object.entries(value)) {
          if (v === null || v === undefined) continue;
          const encodedK = encodeValue(k, isReserved);
          const encodedV = encodeValue(String(v), isReserved);
          const vEmpty = String(v) === '';
          if (named && vEmpty) {
            pieces.push(`${encodedK}${emptyValue}`);
          } else {
            pieces.push(`${encodedK}=${encodedV}`);
          }
        }
      } else {
        // Scalar or single-item array
        const item = Array.isArray(value) ? value[0] : value;
        const encoded = encodeValue(String(item), isReserved);
        if (named) {
          if (encoded === '') {
            pieces.push(`${varSpec.name}${emptyValue}`);
          } else {
            pieces.push(`${varSpec.name}=${encoded}`);
          }
        } else {
          pieces.push(encoded);
        }
      }
    }
  }

  if (pieces.length === 0) {
    return '';
  }

  return prefix + pieces.join(separator);
