  if (maxLength !== null && (Array.isArray(value) || (typeof value === 'object' && value !== null && !(value instanceof Array)))) {
    throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
  }

  if (value === null || value === undefined) {
    return [];
  }

  if (typeof value === 'string') {
    let str = value;
    if (maxLength !== null) {
      // Truncate by code points
      str = [...str].slice(0, maxLength).join('');
    }
    if (str === '') {
      return [];
    }
    return [encodeValue(str, isReserved)];
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    const str = String(value);
    if (maxLength !== null) {
      const truncated = [...str].slice(0, maxLength).join('');
      return [encodeValue(truncated, isReserved)];
    }
    return [encodeValue(str, isReserved)];
  }

  if (Array.isArray(value)) {
    if (explode) {
      const items = [];
      for (const item of value) {
        if (item === null || item === undefined) continue;
        if (typeof item !== 'string' && typeof item !== 'number' && typeof item !== 'boolean') {
          throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
        }
        items.push(encodeValue(String(item), isReserved));
      }
      return items;
    } else {
      const items = [];
      for (const item of value) {
        if (item === null || item === undefined) continue;
        if (typeof item !== 'string' && typeof item !== 'number' && typeof item !== 'boolean') {
          throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
        }
        items.push(encodeValue(String(item), isReserved));
      }
      if (items.length === 0) {
        return [];
      }
      return [items.join(',')];
    }
  }

  if (typeof value === 'object' && value !== null) {
    const keys = Object.keys(value);
    if (keys.length === 0) {
      return [];
    }

    if (explode) {
      const items = [];
      for (const k of keys) {
        const v = value[k];
        if (v === null || v === undefined) continue;
        if (typeof v !== 'string' && typeof v !== 'number' && typeof v !== 'boolean') {
          throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
        }
        const encodedK = encodeValue(k, isReserved);
        const encodedV = encodeValue(String(v), isReserved);
        items.push(`${encodedK}=${encodedV}`);
      }
      return items;
    } else {
      const items = [];
      for (const k of keys) {
        const v = value[k];
        if (v === null || v === undefined) continue;
        if (typeof v !== 'string' && typeof v !== 'number' && typeof v !== 'boolean') {
          throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
        }
        items.push(encodeValue(k, isReserved));
        items.push(encodeValue(String(v), isReserved));
      }
      if (items.length === 0) {
        return [];
      }
      return [items.join(',')];
    }
  }

  // Invalid type
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}"}

