}

function expandExpression(expr, variables) {
  const { operator, variables: vars } = expr;

  // Operator table: [prefix, separator, named, emptyValue]
  const operatorTable = {
    '': ['', ',', false, ''],
    '+': ['', ',', false, ''],
    '#': ['#', ',', false, ''],
    '.': ['.', '.', false, ''],
    '/': ['/', '/', false, ''],
    ';': [';', ';', true, ''],
    '?': ['?', '&', true, '='],
    '&': ['&', '&', true, '=']
  };

  const [prefix, separator, named, emptyValue] = operatorTable[operator];
  const isReserved = operator === '+' || operator === '#';

  const pieces = [];

  for (const varSpec of vars) {
    const value = variables[varSpec.name];

    // Skip absent, null, undefined values
    if (value === null || value === undefined || !Object.prototype.hasOwnProperty.call(variables, varSpec.name)) {
      continue;
    }

    // Validate type and check for composite values with prefix modifier
    if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'boolean' &&
        !Array.isArray(value) && (typeof value !== 'object' || value === null)) {
      throw new UriTemplateError(`value for '${varSpec.name}' is not a string, number or boolean`);
    }

    if (varSpec.maxLength !== null && (Array.isArray(value) || (typeof value === 'object' && value !== null && !(value instanceof Array)))) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${varSpec.name}'`);
    }

    // Handle different value types
    if (Array.isArray(value)) {
      const usableItems = value.filter(v => v !== null && v !== undefined);
      if (usableItems.length === 0) continue;

      // Validate all items
      for (const item of usableItems) {
        if (typeof item !== 'string' && typeof item !== 'number' && typeof item !== 'boolean') {
          throw new UriTemplateError(`value for '${varSpec.name}' is not a string, number or boolean`);
        }
      }

      if (varSpec.explode) {
        // Exploded array: each item is its own piece
        for (const item of usableItems) {
          const encoded = encodeValue(String(item), isReserved);
          if (named) {
            pieces.push(`${varSpec.name}=${encoded}`);
          } else {
            pieces.push(encoded);
          }
        }
      } else {
        // Non-exploded array: all items joined with `,`
        const encodedItems = usableItems.map(item => encodeValue(String(item), isReserved));
        if (named) {
          pieces.push(`${varSpec.name}=${encodedItems.join(',')}`);
        } else {
          pieces.push(encodedItems.join(','));
        }
      }
    } else if (typeof value === 'object' && value !== null) {
      // Object/map
      const entries = Object.entries(value).filter(([, v]) => v !== null && v !== undefined);
      if (entries.length === 0) continue;

      // Validate all values
      for (const [, v] of entries) {
        if (typeof v !== 'string' && typeof v !== 'number' && typeof v !== 'boolean') {
          throw new UriTemplateError(`value for '${varSpec.name}' is not a string, number or boolean`);
        }
      }

      if (varSpec.explode) {
        // Exploded object: each key=value is its own piece
        for (const [k, v] of entries) {
          const encodedK = encodeValue(k, isReserved);
          const encodedV = encodeValue(String(v), isReserved);
          if (encodedV === '') {
            pieces.push(`${encodedK}${emptyValue}`);
          } else {
            pieces.push(`${encodedK}=${encodedV}`);
          }
        }
      } else {
        // Non-exploded object: flatten to key,value,key,value,...
        const flatPairs = [];
        for (const [k, v] of entries) {
          flatPairs.push(encodeValue(k, isReserved));
          flatPairs.push(encodeValue(String(v), isReserved));
        }
        if (named) {
          pieces.push(`${varSpec.name}=${flatPairs.join(',')}`);
        } else {
          pieces.push(flatPairs.join(','));
        }
      }
    } else {
      // Scalar value (string, number, or boolean)
      let str = String(value);

      // Apply prefix modifier
      if (varSpec.maxLength !== null) {
        // Truncate by code points
        str = [...str].slice(0, varSpec.maxLength).join('');
      }

      const encoded = encodeValue(str, isReserved);

      if (named) {
        if (encoded === '') {
          pieces.push(`${varSpec.name}${emptyValue}`);
        } else {
          pieces.push(`${varSpec.name}=${encoded}`);
        }
      } else {
        pieces.push(encoded);
      }
    }
  }

  if (pieces.length === 0) {
    return '';
  }

  return prefix + pieces.join(separator);
}
