/**
 * Resolve one version per package.
 *
 * @param {Record<string, Record<string, {deps?: Record<string, string>}>>} registry Available packages.
 * @param {Record<string, string>} rootDeps Ranges the root asks for.
 * @returns {{resolved: Record<string, string>, order: string[]}} Selection and the order it was made in.
 */
export function resolve(registry, rootDeps) {
  // Validate registry
  if (registry === null || typeof registry !== 'object' || Array.isArray(registry)) {
    throw new ResolveError('BAD_REGISTRY', 'registry must be an object');
  }

  // Validate root dependencies
  if (rootDeps === null || typeof rootDeps !== 'object' || Array.isArray(rootDeps)) {
    throw new ResolveError('BAD_DEPENDENCIES', 'root dependencies must be an object');
  }

  // Validate and parse all registry entries and ranges
  const registryVersions = {}; // packageName -> sorted array of valid versions
  for (const [name, packageEntry] of Object.entries(registry)) {
    if (packageEntry === null || typeof packageEntry !== 'object' || Array.isArray(packageEntry)) {
      throw new ResolveError('BAD_REGISTRY', `registry entry must be an object: ${name}`);
    }

    const versions = [];
    for (const [versionStr, metadata] of Object.entries(packageEntry)) {
      // Parse and validate version
      try {
        parseVersion(versionStr);
      } catch (e) {
        throw e; // Re-throw the BAD_VERSION error
      }

      // Validate metadata
      if (metadata === null || typeof metadata !== 'object' || Array.isArray(metadata)) {
        throw new ResolveError('BAD_REGISTRY', `metadata must be an object: ${name}@${versionStr}`);
      }

      // Validate dependencies if present
      if (metadata.deps !== undefined) {
        if (metadata.deps === null || typeof metadata.deps !== 'object' || Array.isArray(metadata.deps)) {
          throw new ResolveError('BAD_DEPENDENCIES', `dependencies of ${name}@${versionStr} must be an object`);
        }
        // Validate each dependency range
        for (const [depName, depRange] of Object.entries(metadata.deps)) {
          try {
            parseRange(depRange);
          } catch (e) {
            throw e; // Re-throw the BAD_RANGE error
          }
        }
      }

      versions.push(versionStr);
    }

    // Sort versions numerically
    versions.sort(compareVersions);
    registryVersions[name] = versions;
  }

  // Validate and parse all root dependency ranges
  const rootRanges = {};
  for (const [name, range] of Object.entries(rootDeps)) {
    try {
      parseRange(range);
    } catch (e) {
      throw e; // Re-throw the BAD_RANGE error
    }
    rootRanges[name] = range;
  }

  // Resolution algorithm
  const resolved = {}; // name -> version
  const order = []; // selection order
  const constraints = {}; // name -> array of {range, via}
  const pending = new Set(); // names pending selection

  // Seed from root dependencies in ascending name order
  const rootNames = Object.keys(rootRanges).sort();
  for (const name of rootNames) {
    constraints[name] = [{ range: rootRanges[name], via: '<root>' }];
    pending.add(name);
  }

  // Resolution loop
  while (pending.size > 0) {
    // Get lexicographically smallest pending name
    const names = Array.from(pending).sort();
    const name = names[0];
    pending.delete(name);

    // Check if package exists in registry
    if (!registryVersions.hasOwnProperty(name)) {
      throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    }

    // Find candidates: versions that satisfy all constraints
    const available = registryVersions[name];
    const candidates = available.filter(v => {
      for (const constraint of constraints[name]) {
        if (!satisfies(v, constraint.range)) return false;
      }
      return true;
    });

    // No satisfying candidate - conflict
    if (candidates.length === 0) {
      throw new ConflictError(name, constraints[name], available);
    }

    // Pick highest candidate
    const version = candidates[candidates.length - 1];
    resolved[name] = version;
    order.push(name);

    // Build chain for this package
    let chain = '<root>';
    for (const dep of order.slice(0, -1)) {
      chain += ` > ${dep}@${resolved[dep]}`;
    }
    chain += ` > ${name}@${version}`;

    // Get metadata and walk dependencies in ascending name order
    const metadata = registry[name][version];
    const deps = metadata.deps ?? {};
    const depNames = Object.keys(deps).sort();

    for (const depName of depNames) {
      const depRange = deps[depName];

      if (!constraints.hasOwnProperty(depName)) {
        constraints[depName] = [];
      }

      // Add constraint
      constraints[depName].push({ range: depRange, via: chain });

      // If already selected, verify it satisfies the constraint
      if (resolved.hasOwnProperty(depName)) {
        if (!satisfies(resolved[depName], depRange)) {
          throw new ConflictError(depName, constraints[depName], registryVersions[depName]);
        }
      } else {
        // Not selected yet, add to pending
        pending.add(depName);
      }
    }
  }

  // Return result with resolved in ascending name order
  const resolvedKeys = Object.keys(resolved).sort();
  const resolvedOrdered = {};
  for (const key of resolvedKeys) {
    resolvedOrdered[key] = resolved[key];
  }

  return { resolved: resolvedOrdered, order };
}"}

