 *
 * @param {string} text Range to parse.
 * @returns {Array<{operator: string, version: string}>} Comparators, empty for `*`.
 */
export function parseRange(text) {
  if (typeof text !== 'string') {
    throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  }

  const trimmed = text.trim();

  // Empty string is invalid
  if (trimmed === '') {
    throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  }

  // Special case: * alone is valid
  if (trimmed === '*') {
    return [];
  }

  // * cannot appear with other content
  if (trimmed.includes('*')) {
    throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  }

  const comparators = [];
  const parts = trimmed.split(/\s+/);

  for (const part of parts) {
    if (part === '') continue;

    let operator = null;
    let versionStr = null;

    // Try to match operator + version pattern
    let match = part.match(/^(>=|<=|>|<|=)(.+)$/);
    if (match) {
      operator = match[1];
      versionStr = match[2];
    } else if (part[0] === '^' && part.length > 1) {
      // Caret range
      operator = '^';
      versionStr = part.slice(1);
    } else if (part[0] === '~' && part.length > 1) {
      // Tilde range
      operator = '~';
      versionStr = part.slice(1);
    } else if (!part.match(/^[><^~=]/)) {
      // Bare version (no operator)
      operator = '=';
      versionStr = part;
    } else {
      // Invalid: lone operator or malformed
      throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
    }

    // Parse version to validate it
    let version;
    try {
      version = parseVersion(versionStr);
    } catch (e) {
      throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
    }

    // Expand caret and tilde ranges
    if (operator === '^') {
      comparators.push({ operator: '>=', version: versionStr });

      // Upper bound depends on leftmost non-zero part
      let upper;
      if (version.major !== 0) {
        upper = `${version.major + 1}.0.0`;
      } else if (version.minor !== 0) {
        upper = `0.${version.minor + 1}.0`;
      } else {
        upper = `0.0.${version.patch + 1}`;
      }
      comparators.push({ operator: '<', version: upper });
    } else if (operator === '~') {
      comparators.push({ operator: '>=', version: versionStr });
      const upper = `${version.major}.${version.minor + 1}.0`;
      comparators.push({ operator: '<', version: upper });
    } else {
      // Regular operator (=, >=, <=, >, <)
      comparators.push({ operator, version: versionStr });
    }
