 * Resolve one version per package.
 *
 * @param {Record<string, Record<string, {deps?: Record<string, string>}>>} registry Available packages.
 * @param {Record<string, string>} rootDeps Ranges the root asks for.
 * @returns {{resolved: Record<string, string>, order: string[]}} Selection and the order it was made in.
 */
export function resolve(registry, rootDeps) {
  // Import functions from semver.js
  const { parseVersion, parseRange, satisfies, compareVersions, maxSatisfying } = await import('./semver.js');

  // Validate registry
  if (typeof registry !== 'object' || registry === null || Array.isArray(registry)) {
    throw new ResolveError('BAD_REGISTRY', 'registry must be an object');
  }

  // Validate rootDeps
  if (typeof rootDeps !== 'object' || rootDeps === null || Array.isArray(rootDeps)) {
    throw new ResolveError('BAD_DEPENDENCIES', 'root dependencies must be an object');
  }

  // Validate registry entries and parse versions/ranges
  for (const [name, versions] of Object.entries(registry)) {
    if (typeof versions !== 'object' || versions === null || Array.isArray(versions)) {
      throw new ResolveError('BAD_REGISTRY', `registry entry must be an object: ${name}`);
    }

    for (const [versionStr, metadata] of Object.entries(versions)) {
      // Validate version format
      try {
        parseVersion(versionStr);
      } catch (e) {
        throw e; // Re-throw the BAD_VERSION error
      }

      // Validate metadata
      if (typeof metadata !== 'object' || metadata === null || Array.isArray(metadata)) {
        throw new ResolveError('BAD_REGISTRY', `metadata must be an object: ${name}@${versionStr}`);
      }

      // Validate dependencies
      if (metadata.deps !== undefined) {
        if (typeof metadata.deps !== 'object' || metadata.deps === null || Array.isArray(metadata.deps)) {
          throw new ResolveError('BAD_DEPENDENCIES', `dependencies of ${name}@${versionStr} must be an object`);
        }

        // Validate each dependency range
        for (const [depName, range] of Object.entries(metadata.deps)) {
          try {
            parseRange(range);
          } catch (e) {
            throw e; // Re-throw the BAD_RANGE error
          }
        }
      }
    }
  }

  // Validate root dependencies
  for (const [name, range] of Object.entries(rootDeps)) {
    try {
      parseRange(range);
    } catch (e) {
      throw e; // Re-throw the BAD_RANGE error
    }
  }

  // Data structures for resolution
  const constraints = {}; // Map of package name -> array of {range, via}
  const pending = new Set(); // Pending package names
  const resolved = {}; // Map of package name -> selected version
  const order = []; // Order packages were selected
  const chains = {}; // Map of package name -> its chain string

  // Seed pending from root dependencies in ascending name order
  const rootNames = Object.keys(rootDeps).sort();
  for (const name of rootNames) {
    constraints[name] = [{ range: rootDeps[name], via: '<root>' }];
    pending.add(name);
  }

  // Resolution loop
  while (pending.size > 0) {
    // Get lexicographically smallest pending name
    const pendingArray = Array.from(pending).sort();
    const name = pendingArray[0];
    pending.delete(name);

    // Check if package exists in registry
    if (!(name in registry)) {
      throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    }

    const versions = Object.keys(registry[name]).sort(compareVersions);

    // Find candidates that satisfy all constraints
    const pkgConstraints = constraints[name] || [];
    let selected = null;

    for (let i = versions.length - 1; i >= 0; i--) {
      const version = versions[i];
      let satisfiesAll = true;

      for (const { range } of pkgConstraints) {
        if (!satisfies(version, range)) {
          satisfiesAll = false;
          break;
        }
      }

      if (satisfiesAll) {
        selected = version;
        break;
      }
    }

    // No satisfying candidate found
    if (selected === null) {
      throw new ConflictError(name, pkgConstraints, versions);
    }

    // Build chain
    let chain;
    if (pkgConstraints.length > 0) {
      const origin = pkgConstraints[0].via;
      chain = `${origin} > ${name}@${selected}`;
    } else {
      chain = `<root> > ${name}@${selected}`;
    }

    chains[name] = chain;
    resolved[name] = selected;
    order.push(name);

    // Process dependencies
    const metadata = registry[name][selected];
    const deps = metadata.deps || {};
    const depNames = Object.keys(deps).sort();

    for (const depName of depNames) {
      const depRange = deps[depName];

      if (!(depName in constraints)) {
        constraints[depName] = [];
      }

      constraints[depName].push({ range: depRange, via: chain });

      if (depName in resolved) {
        // Already selected - verify it still satisfies
        if (!satisfies(resolved[depName], depRange)) {
          // Conflict!
          throw new ConflictError(depName, constraints[depName], Object.keys(registry[depName] || {}).sort(compareVersions));
        }
      } else {
        // Not yet selected - make it pending
        pending.add(depName);
      }
    }
  }

  // Return resolved packages in ascending name order
  const resultResolved = {};
  for (const name of Object.keys(resolved).sort()) {
    resultResolved[name] = resolved[name];
  }

  return { resolved: resultResolved, order };
}"}

