{"file_path":"src/heap.js","content":"/**
 * Binary min-heap with an index from key to position.
 *
 * Maintains O(log n) push, pop, decreaseKey, setPriority, remove and O(1)
 * has, peek, priorityOf. Entries with equal priority leave in insertion order.
 */
export class IndexedHeap {
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} Maps key to index in #items */
  #index = new Map();

  /** @type {number} Insertion sequence counter */
  #seq = 0;

  /** @returns {number} Number of entries currently held. */
  get size() {
    return this.#items.length;
  }

  /**
   * Adds an entry.
   * @param {string} key Unique key.
   * @param {number} priority Ordering priority; smaller leaves first.
   * @returns {void}
   */
  push(key, priority) {
    // Validate key
    if (typeof key !== 'string') {
      throw new TypeError('key must be a string');
    }

    // Validate priority
    if (!Number.isFinite(priority)) {
      throw new TypeError('priority must be a finite number');
    }

    // Check for duplicates
    if (this.#index.has(key)) {
      throw new Error(`duplicate key: "${key}"`);
    }

    // Add entry with sequence number for stable ordering
    const seq = this.#seq++;
    const pos = this.#items.length;
    const entry = { key, priority, seq };
    this.#items.push(entry);
    this.#index.set(key, pos);

    // Restore heap property
    this.#bubbleUp(pos);
  }

  /**
   * Reads the next entry without removing it.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  peek() {
    if (this.#items.length === 0) return undefined;
    const best = this.#items[0];
    return { key: best.key, priority: best.priority };
  }

  /**
   * Removes and returns the next entry.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  pop() {
    const next = this.peek();
    if (next === undefined) return undefined;

    // Remove root and restore heap
    const lastEntry = this.#items.pop();
    this.#index.delete(next.key);

    if (this.#items.length > 0) {
      this.#items[0] = lastEntry;
      this.#index.set(lastEntry.key, 0);
      this.#bubbleDown(0);
    }

    return next;
  }

  /**
   * Reports whether a key is held.
   * @param {string} key Key to look up.
   * @returns {boolean} True when the key is held.
   */
  has(key) {
    if (typeof key !== 'string') {
      throw new TypeError('key must be a string');
    }
    return this.#index.has(key);
  }

  /**
   * Reads the priority stored for a key.
   * @param {string} key Key to look up.
   * @returns {number | undefined} Stored priority, or undefined when absent.
   */
  priorityOf(key) {
    if (typeof key !== 'string') {
      throw new TypeError('key must be a string');
    }
    const pos = this.#index.get(key);
    if (pos === undefined) return undefined;
    return this.#items[pos].priority;
  }

  /**
   * Lowers the priority of a held key.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority; must not exceed the current one.
   * @returns {void}
   */
  decreaseKey(key, priority) {
    if (typeof key !== 'string') {
      throw new TypeError('key must be a string');
    }
    if (!Number.isFinite(priority)) {
      throw new TypeError('priority must be a finite number');
    }

    const pos = this.#index.get(key);
    if (pos === undefined) {
      throw new ReferenceError(`unknown key: "${key}"`);
    }

    const entry = this.#items[pos];
    if (priority > entry.priority) {
      throw new RangeError(`priority must not increase for "${key}"`);
    }

    entry.priority = priority;
    this.#bubbleUp(pos);
  }

  /**
   * Sets the priority of a held key in either direction.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority.
   * @returns {void}
   */
  setPriority(key, priority) {
    if (typeof key !== 'string') {
      throw new TypeError('key must be a string');
    }
    if (!Number.isFinite(priority)) {
      throw new TypeError('priority must be a finite number');
    }

    const pos = this.#index.get(key);
    if (pos === undefined) {
      throw new ReferenceError(`unknown key: "${key}"`);
    }

    const entry = this.#items[pos];
    const oldPriority = entry.priority;
    entry.priority = priority;

    // Restore heap property based on direction of change
    if (priority < oldPriority) {
      this.#bubbleUp(pos);
    } else if (priority > oldPriority) {
      this.#bubbleDown(pos);
    }
    // If equal, heap is already valid
  }

  /**
   * Removes a held key.
   * @param {string} key Key to remove.
   * @returns {boolean} True when an entry was removed.
   */
  remove(key) {
    if (typeof key !== 'string') {
      throw new TypeError('key must be a string');
    }

    const pos = this.#index.get(key);
    if (pos === undefined) return false;

    // Remove entry and replace with last item
    const lastEntry = this.#items.pop();
    this.#index.delete(key);

    if (pos < this.#items.length) {
      this.#items[pos] = lastEntry;
      this.#index.set(lastEntry.key, pos);

      // Restore heap property
      if (pos > 0) {
        const parentPos = (pos - 1) >> 1;
        if (this.#compare(pos, parentPos) < 0) {
          this.#bubbleUp(pos);
          return true;
        }
      }
      this.#bubbleDown(pos);
    }

    return true;
  }

  /**
   * Empties the heap.
   * @returns {Array<{key: string, priority: number}>} Every entry in pop order.
   */
  drain() {
    const result = [];
    while (this.#items.length > 0) {
      result.push(this.pop());
    }
    return result;
  }

  /**
   * Compare two entries: returns negative if a < b, 0 if equal, positive if a > b.
   * Uses priority as primary key, sequence number as tiebreaker.
   * @param {number} i
   * @param {number} j
   * @returns {number}
   */
  #compare(i, j) {
    const a = this.#items[i];
    const b = this.#items[j];
    if (a.priority !== b.priority) {
      return a.priority - b.priority;
    }
    return a.seq - b.seq;
  }

  /**
   * Bubble entry up from position pos until heap property is satisfied.
   * @param {number} pos
   */
  #bubbleUp(pos) {
    while (pos > 0) {
      const parentPos = (pos - 1) >> 1;
      if (this.#compare(pos, parentPos) >= 0) break;

      // Swap with parent
      [this.#items[pos], this.#items[parentPos]] = [this.#items[parentPos], this.#items[pos]];
      this.#index.set(this.#items[pos].key, pos);
      this.#index.set(this.#items[parentPos].key, parentPos);

      pos = parentPos;
    }
  }

  /**
   * Bubble entry down from position pos until heap property is satisfied.
   * @param {number} pos
   */
  #bubbleDown(pos) {
    while (true) {
      let smallest = pos;
      const left = (pos << 1) + 1;
      const right = (pos << 1) + 2;

      if (left < this.#items.length && this.#compare(left, smallest) < 0) {
        smallest = left;
      }
      if (right < this.#items.length && this.#compare(right, smallest) < 0) {
        smallest = right;
      }

      if (smallest === pos) break;

      // Swap with smallest child
      [this.#items[pos], this.#items[smallest]] = [this.#items[smallest], this.#items[pos]];
      this.#index.set(this.#items[pos].key, pos);
      this.#index.set(this.#items[smallest].key, smallest);

      pos = smallest;
    }
  }
}
"}

