{"file_path":"src/dijkstra.js","content":"import { IndexedHeap } from './heap.js';

/**
 * Computes the distance and predecessor of every node from one source.
 * @param {unknown} graph Weighted directed graph.
 * @param {string} source Node to start from.
 * @returns {{dist: Record<string, number>, prev: Record<string, string | null>}} Distances and predecessors.
 */
export function shortestPaths(graph, source) {
  // Validate graph
  if (typeof graph !== 'object' || graph === null || Array.isArray(graph)) {
    throw new TypeError('graph must be an object');
  }

  // Validate source
  if (typeof source !== 'string') {
    throw new TypeError('source must be a string');
  }

  // Check that source exists in graph
  if (!(source in graph)) {
    throw new ReferenceError(`unknown node: "${source}"`);
  }

  // Validate all nodes and edges
  const nodes = Object.keys(graph);
  for (const node of nodes) {
    const edges = graph[node];
    if (typeof edges !== 'object' || edges === null || Array.isArray(edges)) {
      throw new TypeError(`edge map for node "${node}" must be an object`);
    }

    // Validate all edges from this node
    for (const [target, weight] of Object.entries(edges)) {
      // Check target node exists
      if (!(target in graph)) {
        throw new ReferenceError(`unknown node: "${target}"`);
      }

      // Check weight is positive and finite
      if (!Number.isFinite(weight) || weight <= 0) {
        throw new RangeError(`weight must be positive: "${node}" -> "${target}"`);
      }
    }
  }

  // Initialize distances and predecessors
  const dist = {};
  const prev = {};
  for (const node of nodes) {
    dist[node] = node === source ? 0 : Infinity;
    prev[node] = null;
  }

  // Use heap to drive Dijkstra
  const heap = new IndexedHeap();
  heap.push(source, 0);

  while (heap.size > 0) {
    const { key: u } = heap.pop();

    // For each edge from u
    const edges = graph[u];
    for (const [v, weight] of Object.entries(edges)) {
      const newDist = dist[u] + weight;

      // If we found a shorter path to v
      if (newDist < dist[v]) {
        dist[v] = newDist;
        prev[v] = u;

        // Update heap: if v is already there, decrease its key; otherwise add it
        if (heap.has(v)) {
          heap.decreaseKey(v, newDist);
        } else {
          heap.push(v, newDist);
        }
      } else if (newDist === dist[v] && u < prev[v]) {
        // On tie, pick the smallest predecessor id
        prev[v] = u;
      }
    }
  }

  return { dist, prev };
}

/**
 * Finds one shortest route between two nodes.
 * @param {unknown} graph Weighted directed graph.
 * @param {string} source Node to start from.
 * @param {string} target Node to reach.
 * @returns {{distance: number, path: string[]} | null} Route, or null when unreachable.
 */
export function shortestPath(graph, source, target) {
  // Validate target
  if (typeof target !== 'string') {
    throw new TypeError('target must be a string');
  }

  // Validate target node exists (implicitly done by shortestPaths)
  // But we'll be more explicit for better error messages
  if (typeof graph !== 'object' || graph === null || Array.isArray(graph)) {
    throw new TypeError('graph must be an object');
  }

  if (!(target in graph)) {
    throw new ReferenceError(`unknown node: "${target}"`);
  }

  // Get shortest paths
  const { dist, prev } = shortestPaths(graph, source);

  // Check if target is reachable
  if (dist[target] === Infinity) {
    return null;
  }

  // Reconstruct path from source to target
  const path = [];
  let current = target;
  while (current !== null) {
    path.unshift(current);
    current = prev[current];
  }

  return { distance: dist[target], path };
}
"}

