export function allowedTypes(state) {
  const table = {
    created: ['addItem', 'cancel', 'pay', 'removeItem'],
    paid: ['cancel', 'pack'],
    packed: ['cancel', 'ship'],
    shipped: ['deliver'],
    delivered: ['refund'],
    cancelled: [],
    refunded: [],
  };

  if (!(state in table)) {
    throw new TypeError(`unknown state: ${state}`);
  }

  return [...table[state]];
}

/**
 * Report whether a state accepts no further command.
 *
 * @param {string} state State to look up.
