 * @param {string} pointer JSON Pointer text
 * @returns {string[]} the decoded tokens, empty for the whole-document pointer
 */
export function parsePointer(pointer) {
  if (typeof pointer !== 'string') {
    throw new PointerError('pointer must be a string');
  }

  if (pointer === '') return [];

  if (!pointer.startsWith('/')) {
    throw new PointerError("pointer must be empty or start with '/'");
  }

  const parts = pointer.slice(1).split('/');
  const tokens = [];

  for (const part of parts) {
    let decoded = '';
    for (let i = 0; i < part.length; i++) {
      if (part[i] === '~') {
        if (i + 1 >= part.length) {
          throw new PointerError('invalid escape in pointer token: ~');
        }
        const next = part[i + 1];
        if (next === '0') {
          decoded += '~';
          i++;
        } else if (next === '1') {
          decoded += '/';
          i++;
        } else {
          throw new PointerError(`invalid escape in pointer token: ~${next}`);
        }
      } else {
        decoded += part[i];
      }
    }
    tokens.push(decoded);
  }

  return tokens;
}"}

