  if (pointer === '') return document;
  throw new Error('not implemented');
}","new_string":"export function resolve(document, pointer) {
  const tokens = parsePointer(pointer);

  let current = document;
  let path = '';

  for (const token of tokens) {
    path += '/' + formatPointer([token]).slice(1);

    if (Array.isArray(current)) {
      // Validate array index
      if (token === '-' || token === '') {
        throw new PointerError(`invalid array index: ${token} at ${path}`);
      }

      if (!/^\d+$/.test(token)) {
        throw new PointerError(`invalid array index: ${token} at ${path}`);
      }

      if (token[0] === '0' && token.length > 1) {
        throw new PointerError(`invalid array index: ${token} at ${path}`);
      }

      const index = Number(token);
      if (index >= current.length) {
        throw new PointerError(`index out of range: ${index} at ${path}`);
      }
      current = current[index];
    } else if (current !== null && typeof current === 'object') {
      // Object
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        throw new PointerError(`missing property: ${token} at ${path}`);
      }
      current = current[token];
    } else {
      // Cannot index into primitive
      const type = current === null ? 'null' : typeof current;
      throw new PointerError(`cannot index into ${type} at ${path}`);
    }
  }

  return current;
