{"file_path":"src/patch.js","old_string":"/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *
 * @param {unknown} document JSON data to patch
 * @param {object[]} operations the patch
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  throw new Error('not implemented');
}","new_string":"/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *
 * @param {unknown} document JSON data to patch
 * @param {object[]} operations the patch
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  // Validate inputs
  if (!Array.isArray(operations)) {
    throw new Error('patch must be an array');
  }

  // Check that document and all values are JSON-serializable
  try {
    JSON.stringify(document);
  } catch {
    throw new Error('document is not JSON data');
  }

  // Deep copy the document
  let result = deepCopy(document);

  // Validate all operations before applying any
  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    try {
      validateOperation(op);
    } catch (error) {
      if (error instanceof PointerError) {
        throw new PatchError(error.message, i, { cause: error });
      }
      throw new PatchError(error.message, i);
    }
  }

  // Apply each operation
  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    try {
      result = applyOperation(result, op);
    } catch (error) {
      if (error instanceof PointerError) {
        throw new PatchError(error.message, i, { cause: error });
      }
      throw new PatchError(error.message, i);
    }
  }

  return result;
}

function deepCopy(value) {
  if (value === null) return null;
  if (typeof value !== 'object') return value;

  if (Array.isArray(value)) {
    return value.map(item => deepCopy(item));
  }

  const copy = {};
  for (const key of Object.keys(value)) {
    copy[key] = deepCopy(value[key]);
  }
  return copy;
}

function validateOperation(op) {
  if (typeof op !== 'object' || op === null) {
    throw new Error('operation must be an object');
  }

  if (typeof op.op !== 'string') {
    throw new Error(`unknown operation: ${op.op}`);
  }

  switch (op.op) {
    case 'add':
      if (!('path' in op)) throw new Error('add requires a path');
      if (!('value' in op)) throw new Error('add requires a value');
      validatePointer(op.path);
      validateJsonValue(op.value);
      break;
    case 'remove':
      if (!('path' in op)) throw new Error('remove requires a path');
      validatePointer(op.path);
      break;
    case 'replace':
      if (!('path' in op)) throw new Error('replace requires a path');
      if (!('value' in op)) throw new Error('replace requires a value');
      validatePointer(op.path);
      validateJsonValue(op.value);
      break;
    case 'move':
      if (!('from' in op)) throw new Error('move requires a from');
      if (!('path' in op)) throw new Error('move requires a path');
      validatePointer(op.from);
      validatePointer(op.path);
      break;
    case 'copy':
      if (!('from' in op)) throw new Error('copy requires a from');
      if (!('path' in op)) throw new Error('copy requires a path');
      validatePointer(op.from);
      validatePointer(op.path);
      break;
    case 'test':
      if (!('path' in op)) throw new Error('test requires a path');
      if (!('value' in op)) throw new Error('test requires a value');
      validatePointer(op.path);
      validateJsonValue(op.value);
      break;
    default:
      throw new Error(`unknown operation: ${op.op}`);
  }
}

function validatePointer(pointer) {
  if (typeof pointer !== 'string') {
    throw new PointerError('pointer must be a string');
  }
  parsePointer(pointer);
}

function validateJsonValue(value) {
  try {
    JSON.stringify(value);
  } catch {
    throw new Error('value is not JSON data');
  }
}

function applyOperation(document, op) {
  switch (op.op) {
    case 'add':
      return applyAdd(document, op.path, op.value);
    case 'remove':
      return applyRemove(document, op.path);
    case 'replace':
      return applyReplace(document, op.path, op.value);
    case 'move':
      return applyMove(document, op.from, op.path);
    case 'copy':
      return applyCopy(document, op.from, op.path);
    case 'test':
      return applyTest(document, op.path, op.value);
  }
}

function applyAdd(document, pointer, value) {
  const tokens = parsePointer(pointer);

  if (tokens.length === 0) {
    // Replace whole document
    return deepCopy(value);
  }

  const result = deepCopy(document);
  const target = getParentAndKey(result, tokens);

  if (target.parent === null) {
    // Root replacement
    return deepCopy(value);
  }

  const { parent, key } = target;
  const copiedValue = deepCopy(value);

  if (Array.isArray(parent)) {
    if (key === '-') {
      parent.push(copiedValue);
    } else {
      const index = validateArrayIndex(key, parent.length, pointer);
      if (index > parent.length) {
        throw new PointerError(`index out of range: ${index} at ${pointer}`);
      }
      parent.splice(index, 0, copiedValue);
    }
  } else {
    parent[key] = copiedValue;
  }

  return result;
}

