import { UriTemplateError, parse } from './parse.js';

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  if (typeof variables !== 'object' || variables === null) {
    throw new UriTemplateError('variables must be an object');\n  }

  const parts = parse(template);
  let result = '';

  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeLiteral(part.value);
    } else {
      // expression
      result += expandExpression(part.operator, part.variables, variables);
    }
  }

  return result;
}

// Operator configuration: [prefix, separator, named, emptyValueText]
const OPERATORS = {
  '': ['', ',', false, ''],
  '+': ['', ',', false, ''],
  '#': ['#', ',', false, ''],
  '.': ['.', '.', false, ''],
  '/': ['/', '/', false, ''],
  ';': [';', ';', true, ''],
  '?': ['?', '&', true, '='],
  '&': ['&', '&', true, '='],
};

function expandExpression(operator, variables, variableMap) {
  const [prefix, separator, named, emptyValueText] = OPERATORS[operator];

  const pieces = [];

  for (const variable of variables) {
    const { name, explode, maxLength } = variable;

    // Get value from variables, using own properties only
    let value = Object.prototype.hasOwnProperty.call(variableMap, name)
      ? variableMap[name]
      : undefined;

    // Skip missing, null, undefined
    if (value === null || value === undefined) {
      continue;
    }

    // Process based on type
    let varPieces = [];

    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
      // Scalar value
      let str = String(value);

      // Apply prefix modifier to strings only
      if (typeof value === 'string' && maxLength !== null) {
        str = truncateByCodePoints(str, maxLength);
      }

      if (named) {
        const encoded = encodeValue(str, operator);
        if (encoded === '') {
          varPieces.push(name + emptyValueText);
        } else {
          varPieces.push(`${name}=${encoded}`);
        }
      } else {
        varPieces.push(encodeValue(str, operator));
      }
    } else if (Array.isArray(value)) {
      // Array value
      if (maxLength !== null) {
        throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
      }

      const usableItems = value.filter(
        (item) => item !== null && item !== undefined && isValidValue(item)
      );

      if (usableItems.length === 0) {
        continue;
      }

      if (explode) {
        for (const item of usableItems) {
          const encoded = encodeValue(String(item), operator);
          if (named) {
            varPieces.push(`${name}=${encoded}`);
          } else {
            varPieces.push(encoded);
          }
        }
      } else {
        const encoded = usableItems.map((item) => encodeValue(String(item), operator)).join(',');
        if (named) {
          varPieces.push(`${name}=${encoded}`);
        } else {
          varPieces.push(encoded);
        }
      }
    } else if (typeof value === 'object') {
      // Object value
      if (maxLength !== null) {
        throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
      }

      const pairs = [];
      for (const key in value) {
        if (Object.prototype.hasOwnProperty.call(value, key)) {
          const val = value[key];
          if (val !== null && val !== undefined && isValidValue(val)) {
            pairs.push([key, String(val)]);
          }
        }
      }

      if (pairs.length === 0) {
        continue;
      }

      if (explode) {
        for (const [key, val] of pairs) {
          const encodedKey = encodeValue(key, operator);
          const encodedVal = encodeValue(val, operator);

          if (named) {
            if (encodedVal === '') {
              varPieces.push(`${encodedKey}=${emptyValueText}`);
            } else {
              varPieces.push(`${encodedKey}=${encodedVal}`);
            }
          } else {
            varPieces.push(`${encodedKey}=${encodedVal}`);
          }
        }
      } else {
        const flattened = [];
        for (const [key, val] of pairs) {
          flattened.push(encodeValue(key, operator));
          flattened.push(encodeValue(val, operator));
