  const codePoint = char.codePointAt(0);

  if (codePoint <= 0x7f) {
    return [codePoint];
  } else if (codePoint <= 0x7ff) {
    return [
      0xc0 | (codePoint >> 6),
      0x80 | (codePoint & 0x3f),
    ];
  } else if (codePoint <= 0xffff) {
    return [
      0xe0 | (codePoint >> 12),
      0x80 | ((codePoint >> 6) & 0x3f),
      0x80 | (codePoint & 0x3f),
