  '+': ['', ',', false, ''],
  '#': ['#', ',', false, ''],
  '.': ['.', '.', false, ''],
  '/': ['/', '/', false, ''],
  ';': [';', ';', true, ''],
  '?': ['?', '&', true, '='],
  '&': ['&', '&', true, '='],
};

function expandExpression(operator, variables, variableMap) {
  const [prefix, separator, named, emptyValueText] = OPERATORS[operator];

  const pieces = [];

  for (const variable of variables) {
    const { name, explode, maxLength } = variable;

    // Get value from variables, using own properties only
    let value = Object.prototype.hasOwnProperty.call(variableMap, name)
      ? variableMap[name]
      : undefined;

    // Skip missing, null, undefined
    if (value === null || value === undefined) {
