{"file_path":"src/parse.js","content":"/** URI template parsing into literal and expression parts. */

/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  if (template === '') return [];

  const parts = [];
  let i = 0;
  let literal = '';

  while (i < template.length) {
    const ch = template[i];

    if (ch === '{') {
      // Save accumulated literal
      if (literal) {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }

      const exprStart = i;
      i++; // skip '{'

      // Parse operator
      let operator = '';
      if (i < template.length) {
        const potentialOp = template[i];

        // Check for reserved operators first
        if ('=,!@|'.includes(potentialOp)) {
          throw new UriTemplateError(`reserved operator '${potentialOp}' at ${exprStart}`, exprStart);
        }

        // Check for valid operators
        if ('+-#./?;&'.includes(potentialOp)) {
          operator = potentialOp;
          i++;
        }
      }

      // Check for empty expression or empty variable specification
      if (i >= template.length || template[i] === '}') {
        if (operator) {
          throw new UriTemplateError(`empty variable specification at ${exprStart}`, exprStart);
        } else {
          throw new UriTemplateError(`empty expression at ${exprStart}`, exprStart);
        }
      }

      // Parse variables
      const variables = [];

      while (i < template.length && template[i] !== '}') {
        // Parse variable specification (name with optional modifiers)
        let varSpec = '';
        const varStart = i;

        while (i < template.length && template[i] !== ',' && template[i] !== '}') {
          varSpec += template[i];
          i++;
        }

        if (!varSpec) {
          throw new UriTemplateError(`empty variable specification at ${exprStart}`, exprStart);
        }

        // Parse the variable specification
        const { name, explode, maxLength } = parseVarSpec(varSpec, exprStart);

        variables.push({ name, explode, maxLength });

        // Parse comma separator
        if (i < template.length && template[i] === ',') {
          i++;
          // Check for trailing comma
          if (i < template.length && template[i] === '}') {
            throw new UriTemplateError(`empty variable specification at ${exprStart}`, exprStart);
          }
        }
      }

      if (i >= template.length) {
        throw new UriTemplateError(`unterminated expression at ${exprStart}`, exprStart);
      }

      i++; // skip '}'

      parts.push({ type: 'expression', operator, variables });

    } else if (ch === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      literal += ch;
      i++;
    }
  }

  if (literal) {
    parts.push({ type: 'literal', value: literal });
  }

  return parts;
}

function parseVarSpec(spec, exprStart) {
  // Parse: name [*] [:digits]
  // or: name [:digits] [*]
  // but not both * and :digits

  let name = '';
  let explode = false;
  let maxLength = null;
  let i = 0;

  // Parse name
  while (i < spec.length && spec[i] !== '*' && spec[i] !== ':') {
    name += spec[i];
    i++;
  }

  if (!name) {
    throw new UriTemplateError(`invalid variable name '${spec}' at ${exprStart}`, exprStart);
  }

  // Validate name
  if (!isValidVarName(name)) {
    throw new UriTemplateError(`invalid variable name '${name}' at ${exprStart}`, exprStart);
  }

  // Parse modifiers
  while (i < spec.length) {
    if (spec[i] === '*') {
      if (maxLength !== null) {
        // Can't have * after :, show up to the *
        throw new UriTemplateError(`invalid variable name '${spec.slice(0, i)}' at ${exprStart}`, exprStart);
      }
      explode = true;
      i++;
      // Check if there's anything after *
      if (i < spec.length) {
        // There's stuff after *, show up to and including the *
        throw new UriTemplateError(`invalid variable name '${spec.slice(0, i)}' at ${exprStart}`, exprStart);
      }
    } else if (spec[i] === ':') {
      if (explode) {
        // Can't have : after *, show up to before the :
        throw new UriTemplateError(`invalid variable name '${spec.slice(0, i)}' at ${exprStart}`, exprStart);
      }
      i++; // skip ':'

      // Parse modifier value (digits 1-9999 with no leading zero)
      let modValue = '';
      const modStart = i;
      while (i < spec.length && /\d/.test(spec[i])) {
        modValue += spec[i];
        i++;
      }

      if (!modValue || modValue[0] === '0' || parseInt(modValue) > 9999) {
        throw new UriTemplateError(`invalid prefix modifier ':${modValue}' at ${exprStart}`, exprStart);
      }

      maxLength = parseInt(modValue);

      // Check if there's a * after the prefix modifier, which is invalid
      if (i < spec.length && spec[i] === '*') {
        // Show up to but not including the *
        throw new UriTemplateError(`invalid variable name '${spec.slice(0, i)}' at ${exprStart}`, exprStart);
      }
    } else {
      i++;
    }
  }

  return { name, explode, maxLength };
}

function isHexDigit(c) {
  return /[0-9a-fA-F]/.test(c);
}

function isValidVarName(name) {
  if (!name) return false;

  // Dots can't be at start or end
  if (name[0] === '.' || name[name.length - 1] === '.') return false;
  if (name.includes('..')) return false;

  // Each character must be valid
  for (let i = 0; i < name.length; i++) {
    const ch = name[i];

    if (ch === '%') {
      if (i + 2 >= name.length) return false;
      if (!isHexDigit(name[i + 1]) || !isHexDigit(name[i + 2])) return false;
      i += 2;
    } else if (/[a-zA-Z0-9_.]/.test(ch)) {
      // Valid character
    } else {
      return false;
    }
  }

  return true;
}
"}

