 * Prefix index over Unicode strings.
 *
 * A real trie: one node per distinct prefix, walked by Unicode code point so
 * a character outside the basic plane is a single step and never a pair of
 * surrogate halves.
 */

/**
 * Splits a string into an array of single code point strings.
 * @param {string} str String to split.
 * @returns {string[]} One entry per code point.
 */
function codePoints(str) {
  return [...str];
}

/**
 * Sorts a map's keys (single code point strings) by code point.
 * @param {Map<string, unknown>} map Map whose keys to sort.
 * @returns {string[]} Keys ordered by code point.
 */
function sortedKeys(map) {
  return [...map.keys()].sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
}

class Node {
  /** @type {Map<string, Node>} */
  children = new Map();

  /** @type {boolean} */
  hasValue = false;

  /** @type {unknown} */
  value = undefined;

  /** @type {number} Number of stored words in this node's subtree, itself included. */
  count = 0;
}

export class Trie {
