      i++;
      continue;
    }

    // Number literal
    if (/\d/.test(input[i]) || (input[i] === '.' && i + 1 < input.length && /\d/.test(input[i + 1]))) {
      const start = i;
      let hasDecimal = false;

      // Parse integer or starting decimal part
      if (input[i] === '.') {
        hasDecimal = true;
        i++;
      } else {
        while (i < input.length && /\d/.test(input[i])) {
          i++;
        }
        if (i < input.length && input[i] === '.') {
          hasDecimal = true;
          i++;
        }
