      // Parse decimal digits
      if (hasDecimal) {
        if (i >= input.length || !/\d/.test(input[i])) {
          throw new ExprError(`malformed number at ${start}`, start);
        }
        while (i < input.length && /\d/.test(input[i])) {
          i++;
        }
