      // Parse exponent
      if (i < input.length && /[eE]/.test(input[i])) {
        i++;
        if (i < input.length && /[+-]/.test(input[i])) {
          i++;
        }
        if (i >= input.length || !/\d/.test(input[i])) {
          throw new ExprError(`malformed number at ${start}`, start);
        }
        while (i < input.length && /\d/.test(input[i])) {
          i++;
        }
      }

      // Check for invalid continuation
      if (i < input.length && /[a-zA-Z_]/.test(input[i])) {
        throw new ExprError(`malformed number at ${start}`, start);
      }

      tokens.push({
        type: 'number',
        value: Number(input.slice(start, i)),
        index: start,
      });
      continue;
    }

    // Name (identifier)
    if (/[a-zA-Z_]/.test(input[i])) {
      const start = i;
      while (i < input.length && /[a-zA-Z0-9_]/.test(input[i])) {
        i++;
      }
      tokens.push({
        type: 'name',
        value: input.slice(start, i),
        index: start,
      });
      continue;
    }

    // Operators
    if (/[+\-*/%^]/.test(input[i])) {
      tokens.push({
        type: 'operator',
        value: input[i],
        index: i,
      });
      i++;
      continue;
    }

    // Punctuation
    if (input[i] === '(') {
      tokens.push({
        type: 'lparen',
        value: '(',
        index: i,
      });
      i++;
      continue;
    }
    if (input[i] === ')') {
      tokens.push({
        type: 'rparen',
        value: ')',
        index: i,
      });
      i++;
      continue;
    }
    if (input[i] === ',') {
      tokens.push({
        type: 'comma',
        value: ',',
        index: i,
      });
      i++;
      continue;
    }

    // Unexpected character
    throw new ExprError(`unexpected character '${input[i]}' at ${i}`, i);
  }

