{"file_path":"src/parse.js","content":"/** Precedence-climbing parser producing the expression tree. */

import { ExprError, tokenize } from './tokenize.js';

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  function current() {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function advance() {
    pos++;
  }

  function parseExpression() {
    return parseAdditive();
  }

  function parseAdditive() {
    let left = parseMultiplicative();

    while (current()) {
      const token = current();
      if (token.type !== 'operator' || (token.value !== '+' && token.value !== '-')) break;

      const op = token.value;
      const opIndex = token.index;
      advance();
      const right = parseMultiplicative();
      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseMultiplicative() {
    let left = parseExponentiation();

    while (current()) {
      const token = current();
      if (token.type !== 'operator' || (token.value !== '*' && token.value !== '/' && token.value !== '%')) break;

      const op = token.value;
      const opIndex = token.index;
      advance();
      const right = parseExponentiation();
      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseExponentiation() {
    let left = parseUnary();

    // ^ is right-associative
    if (current() && current().type === 'operator' && current().value === '^') {
      const opIndex = current().index;
      advance();
      const right = parseExponentiation(); // right-associative
      left = {
        type: 'binary',
        op: '^',
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseUnary() {
    const token = current();

    if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      const op = token.value;
      const index = token.index;
      advance();
      const operand = parseUnary(); // recursive for multiple unary operators
      return {
        type: 'unary',
        op,
        operand,
        index,
      };
    }

    return parsePrimary();
  }

  function parsePrimary() {
    const token = current();

    if (!token) {
      throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    }

    // Number
    if (token.type === 'number') {
      advance();
      return {
        type: 'number',
        value: token.value,
        index: token.index,
      };
    }

    // Variable or function call
    if (token.type === 'name') {
      const name = token.value;
      const index = token.index;
      advance();

      // Check for function call
      if (current() && current().type === 'lparen') {
        advance(); // consume '('
        const args = [];

        if (current() && current().type !== 'rparen') {
          args.push(parseExpression()); // parse first argument

          while (current() && current().type === 'comma') {
            advance(); // consume ','
            args.push(parseExpression()); // parse next argument
          }
        }

        const closeToken = current();
        if (!closeToken || closeToken.type !== 'rparen') {
          throw new ExprError(`missing closing parenthesis at ${input.length}`, input.length);
        }
        advance();
        return {
          type: 'call',
          name,
          args,
          index,
        };
      }

      return {
        type: 'variable',
        name,
        index,
      };
    }

    // Parenthesized expression
    if (token.type === 'lparen') {
      advance();
      const expr = parseExpression();
      const closeToken = current();
      if (!closeToken || closeToken.type !== 'rparen') {
        throw new ExprError(`missing closing parenthesis at ${input.length}`, input.length);
      }
      advance();
      return expr;
    }

    // Unexpected token
    throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
  }

  if (!tokens.length) {
    throw new ExprError(`unexpected end of input at 0`, 0);
  }

  const expr = parseExpression();

  if (current()) {
    const token = current();
    throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
  }

  return expr;
}
"}

