import { IndexedHeap } from './heap.js';

/**
 * Computes the distance and predecessor of every node from one source.
 * @param {unknown} graph Weighted directed graph.
 * @param {string} source Node to start from.
 * @returns {{dist: Record<string, number>, prev: Record<string, string | null>}} Distances and predecessors.
 */
export function shortestPaths(graph, source) {
  // Validate graph
  if (graph === null || Array.isArray(graph) || typeof graph !== 'object') {
    throw new TypeError('graph must be an object');
  }
  if (typeof source !== 'string') {
    throw new TypeError('source must be a string');
  }

  // Validate all nodes exist and build node list
  const nodes = Object.keys(graph);
  if (!nodes.includes(source)) {
    throw new ReferenceError(`unknown node: "${source}"`);
  }

  // Validate graph structure and weights
  for (const node of nodes) {
    const edges = graph[node];
    if (edges === null || Array.isArray(edges) || typeof edges !== 'object') {
      throw new TypeError(`edge map for node "${node}" must be an object`);
    }
    for (const [target, weight] of Object.entries(edges)) {
      if (!nodes.includes(target)) {
        throw new ReferenceError(`unknown node: "${target}"`);
      }
      if (typeof weight !== 'number' || !isFinite(weight) || weight <= 0) {
        throw new RangeError(`weight must be positive: "${node}" -> "${target}"`);
      }
    }
  }

  // Initialize distances and predecessors
  const dist = {};
  const prev = {};
  for (const node of nodes) {
    dist[node] = Infinity;
    prev[node] = null;
  }
  dist[source] = 0;

  // Use heap to drive the search
  const heap = new IndexedHeap();
  heap.push(source, 0);

  while (heap.size > 0) {
    const current = heap.pop();
    const currentDist = current.priority;

    // Skip if we've already found a better path
    if (currentDist > dist[current.key]) {
      continue;
    }

    // Check all successors
    const edges = graph[current.key];
    for (const [target, weight] of Object.entries(edges)) {
      const newDist = currentDist + weight;

      if (newDist < dist[target]) {
        dist[target] = newDist;
        prev[target] = current.key;
        if (heap.has(target)) {
          heap.setPriority(target, newDist);
        } else {
          heap.push(target, newDist);
        }
      } else if (newDist === dist[target] && current.key < (prev[target] || '')) {
        // Tie-breaking: choose smallest predecessor id
        prev[target] = current.key;
