import { arraysEqual, cloneJSON, deepEqualJSON, isPlainObject, isProperPrefix, setOwn, typeName } from './utils.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

const ARRAY_INDEX = /^(0|[1-9]\d*)$/;

/**
 * Insert a value into an array container for `add`, allowing an index equal
 * to the array's length and the `-` token to append.
 *
 * @param {unknown[]} parent the array to insert into
 * @param {string} token the raw (decoded) last reference token
 * @param {string[]} tokens all tokens of the pointer, for the error message
 * @param {unknown} value the value to insert
 */
function insertArrayValue(parent, token, tokens, value) {
  const fullPointer = formatPointer(tokens);
  let index;
  if (token === '-') {
    index = parent.length;
  } else {
    if (!ARRAY_INDEX.test(token)) {
      throw new PointerError(`invalid array index: ${token} at ${fullPointer}`, fullPointer);
    }
    index = Number(token);
    if (index > parent.length) {
      throw new PointerError(`index out of range: ${token} at ${fullPointer}`, fullPointer);
    }
  }
  parent.splice(index, 0, value);
}

/**
 * Apply `add`: creates or overwrites an object member, or inserts into an
 * array before the given index.
 *
 * @param {unknown} root the document being mutated
 * @param {string} path pointer to the target
 * @param {unknown} value the raw value to insert, cloned and JSON-checked
 * @returns {unknown} the resulting document
 */
function addOp(root, path, value) {
  const clonedValue = cloneJSON(value, 'value is not JSON data');
  const tokens = parsePointer(path);
  if (tokens.length === 0) return clonedValue;
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const parent = resolve(root, parentPointer);
  const token = tokens[tokens.length - 1];
  if (Array.isArray(parent)) {
    insertArrayValue(parent, token, tokens, clonedValue);
  } else if (isPlainObject(parent)) {
    setOwn(parent, token, clonedValue);
  } else {
    const fullPointer = formatPointer(tokens);
    throw new PointerError(`cannot index into ${typeName(parent)} at ${fullPointer}`, fullPointer);
  }
  return root;
}

/**
 * Apply `remove`: deletes an existing object member or array element.
 *
 * @param {unknown} root the document being mutated
 * @param {string} path pointer to the target, which must exist
 * @returns {unknown} the resulting document
 */
function removeOp(root, path) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) throw new Error('cannot remove the whole document');
  resolve(root, path);
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const parent = resolve(root, parentPointer);
  const token = tokens[tokens.length - 1];
