/** Failure raised while parsing or resolving a pointer. */
export class PointerError extends Error {
  /**
   * @param {string} message reason, including the pointer position when known
   * @param {unknown} [pointer] the pointer the failure came from
   */
  constructor(message, pointer) {
    super(message);
    this.name = 'PointerError';
    this.pointer = pointer;
  }
}

const hasOwn = (value, key) => Object.prototype.hasOwnProperty.call(value, key);

/** True when a token is a valid array index: `0` or digits with no leading zero. */
export function isValidArrayIndexToken(token) {
  return /^(0|[1-9][0-9]*)$/.test(token);
}

/** Name a leaf value for "cannot index into" style messages. */
export function typeName(value) {
  if (value === null) return 'null';
  return typeof value;
}

function decodeToken(token) {
  let result = '';
  for (let i = 0; i < token.length; i += 1) {
    const char = token[i];
    if (char === '~') {
      i += 1;
      const next = token[i];
      if (next === '0') result += '~';
      else if (next === '1') result += '/';
      else throw new PointerError(`invalid escape in pointer token: ~${next === undefined ? '' : next}`);
    } else {
      result += char;
    }
  }
  return result;
}

/**
 * Split a pointer into decoded reference tokens.
 *
 * @param {string} pointer JSON Pointer text
 * @returns {string[]} the decoded tokens, empty for the whole-document pointer
 */
export function parsePointer(pointer) {
  if (typeof pointer !== 'string') throw new Error('pointer must be a string');
  if (pointer === '') return [];
  if (pointer[0] !== '/') throw new PointerError("pointer must be empty or start with '/'", pointer);
  return pointer.slice(1).split('/').map(decodeToken);
}

/**
 * Join reference tokens into a pointer.
 *
 * @param {string[]} tokens reference tokens
 * @returns {string} the pointer text, empty for no tokens
 */
export function formatPointer(tokens) {
  if (!Array.isArray(tokens)) throw new Error('tokens must be an array');
  return tokens
    .map((token) => {
      if (typeof token !== 'string') throw new Error('reference token must be a string');
      return `/${token.split('~').join('~0').split('/').join('~1')}`;
    })
    .join('');
}

function step(current, token, pointerSoFar) {
  if (Array.isArray(current)) {
    if (!isValidArrayIndexToken(token)) {
      throw new PointerError(`invalid array index: ${token} at ${pointerSoFar}`, pointerSoFar);
    }
    const index = Number(token);
    if (index >= current.length) {
      throw new PointerError(`index out of range: ${token} at ${pointerSoFar}`, pointerSoFar);
    }
    return current[index];
  }
  if (current !== null && typeof current === 'object') {
    if (!hasOwn(current, token)) {
      throw new PointerError(`missing property: ${token} at ${pointerSoFar}`, pointerSoFar);
    }
    return current[token];
  }
  throw new PointerError(`cannot index into ${typeName(current)} at ${pointerSoFar}`, pointerSoFar);
}

/**
 * Walk decoded tokens against a document, returning the selected value.
 *
 * @param {unknown} document JSON data to walk
 * @param {string[]} tokens decoded reference tokens
 * @returns {unknown} the value the tokens select
 */
export function walk(document, tokens) {
  let current = document;
  for (let i = 0; i < tokens.length; i += 1) {
    current = step(current, tokens[i], formatPointer(tokens.slice(0, i + 1)));
  }
  return current;
}

/**
 * Resolve a pointer against a document.
 *
 * @param {unknown} document JSON data to walk
 * @param {string} pointer JSON Pointer text
 * @returns {unknown} the value the pointer selects
 */
export function resolve(document, pointer) {
  if (pointer === '') return document;
  return walk(document, parsePointer(pointer));
}
