export function allowedTypes(state) {
  const transitions = {
    created: ['addItem', 'cancel', 'pay', 'removeItem'],
    paid: ['cancel', 'pack'],
    packed: ['cancel', 'ship'],
    shipped: ['deliver'],
    delivered: ['refund'],
    cancelled: [],
    refunded: [],
  };

  if (!(state in transitions)) {
    throw new TypeError(`unknown state: ${state}`);
  }

  return [...transitions[state]];
