   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    // Structural validation - throw for malformed commands
    if (typeof command !== 'object' || command === null) {
      throw new TypeError('command must be an object');
    }

    const { type, commandId, at } = command;

    if (!COMMAND_TYPES.includes(type)) {
      throw new TypeError(`unknown command type: ${type}`);
    }

    if (typeof commandId !== 'string' || commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }

    if (!Number.isInteger(at) || at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    // Check for replayed command
    const existingEntry = this.#audit.find((e) => e.commandId === commandId);
    if (existingEntry) {
      const isOk = existingEntry.ok === true;
      return {
        ok: isOk,
        state: this.#state,
        seq: existingEntry.seq,
        replayed: true,
        ...(isOk ? {} : { code: existingEntry.code, message: this.#getMessageForCode(existingEntry.code) }),
      };
    }

    // Check clock regression
    let auditAt = at;
    if (at < this.#clockMs) {
      // Record rejection with current clock
      const entry = {
        seq: this.#audit.length + 1,
        commandId,
        type,
        at: this.#clockMs,
        from: this.#state,
        to: this.#state,
        ok: false,
        code: 'CLOCK_REGRESSION',
      };
      this.#audit.push(entry);
      return {
        ok: false,
        code: 'CLOCK_REGRESSION',
        message: 'command timestamp is earlier than the order clock',
        state: this.#state,
        seq: entry.seq,
        replayed: false,
      };
    }

    // Update clock to command's timestamp
    auditAt = at;
    this.#clockMs = at;

    // Check if current state allows this command
    const allowed = allowedTypes(this.#state);
    if (!allowed.includes(type)) {
      const entry = {
        seq: this.#audit.length + 1,
        commandId,
        type,
        at: auditAt,
        from: this.#state,
        to: this.#state,
        ok: false,
        code: 'BAD_STATE',
      };
      this.#audit.push(entry);
      return {
        ok: false,
        code: 'BAD_STATE',
        message: `cannot apply ${type} in state ${this.#state}`,
        state: this.#state,
        seq: entry.seq,
        replayed: false,
      };
    }

