    const validation = this.#validateCommand(command);
    if (validation.error) {
      const entry = {
        seq: this.#audit.length + 1,
        commandId,
        type,
        at: auditAt,
        from: this.#state,
        to: this.#state,
        ok: false,
        code: validation.code,
      };
      this.#audit.push(entry);
      return {
        ok: false,
        code: validation.code,
        message: validation.message,
        state: this.#state,
        seq: entry.seq,
        replayed: false,
