import { UriTemplateError, parse } from './parse.js';

const UNRESERVED_RE = /^[A-Za-z0-9\-._~]$/;
const RESERVED_CHARS = ":/?#[]@!$&'()*+,;=";

const OPERATORS = {
  '': { prefix: '', separator: ',', named: false, ifEmpty: '', literalStyle: false },
  '+': { prefix: '', separator: ',', named: false, ifEmpty: '', literalStyle: true },
  '#': { prefix: '#', separator: ',', named: false, ifEmpty: '', literalStyle: true },
  '.': { prefix: '.', separator: '.', named: false, ifEmpty: '', literalStyle: false },
  '/': { prefix: '/', separator: '/', named: false, ifEmpty: '', literalStyle: false },
  ';': { prefix: ';', separator: ';', named: true, ifEmpty: '', literalStyle: false },
  '?': { prefix: '?', separator: '&', named: true, ifEmpty: '=', literalStyle: false },
  '&': { prefix: '&', separator: '&', named: true, ifEmpty: '=', literalStyle: false },
};

function encodeUtf8Char(char) {
  const bytes = Buffer.from(char, 'utf8');
  let out = '';
  for (const byte of bytes) {
    out += `%${byte.toString(16).toUpperCase().padStart(2, '0')}`;
  }
  return out;
}

/** Encode keeping unreserved chars, reserved chars, and existing percent-triplets. */
function encodeLiteral(str) {
  let result = '';
  let i = 0;
  while (i < str.length) {
    if (str[i] === '%' && /^[0-9A-Fa-f]{2}$/.test(str.slice(i + 1, i + 3))) {
      result += str.slice(i, i + 3);
      i += 3;
      continue;
    }
    const codePoint = str.codePointAt(i);
    const char = String.fromCodePoint(codePoint);
    if (UNRESERVED_RE.test(char) || RESERVED_CHARS.includes(char)) {
      result += char;
    } else {
      result += encodeUtf8Char(char);
    }
    i += char.length;
  }
  return result;
}

/** Encode keeping only unreserved characters. */
function encodeUnreserved(str) {
  let result = '';
  for (const char of str) {
    result += UNRESERVED_RE.test(char) ? char : encodeUtf8Char(char);
  }
  return result;
}

function isScalar(value) {
  return (
    typeof value === 'string' ||
    typeof value === 'boolean' ||
    (typeof value === 'number' && Number.isFinite(value))
  );
}

function scalarToString(value) {
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  return String(value);
}

function assertScalar(value, name) {
  if (!isScalar(value)) {
    throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
  }
}

function truncate(str, maxLength) {
  if (maxLength === null) return str;
  return Array.from(str).slice(0, maxLength).join('');
}

/**
 * Build the expansion pieces contributed by a single variable specification.
 *
 * @returns {string[]} pieces to join with the operator's separator, empty if no contribution
 */
function buildPieces(spec, rawValue, opConfig, encodeFn) {
  if (rawValue === null || rawValue === undefined) return [];

  if (Array.isArray(rawValue)) {
    const members = rawValue.filter((item) => item !== null && item !== undefined);
    if (members.length === 0) return [];
    for (const item of members) assertScalar(item, spec.name);
    if (spec.maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${spec.name}'`);
    }
    if (!spec.explode) {
      const joined = members.map((item) => encodeFn(scalarToString(item))).join(',');
      const piece = opConfig.named ? `${spec.name}=${joined}` : joined;
      return [piece];
    }
    return members.map((item) => {
      const encoded = encodeFn(scalarToString(item));
      if (!opConfig.named) return encoded;
      return encoded === '' ? `${spec.name}${opConfig.ifEmpty}` : `${spec.name}=${encoded}`;
    });
  }

  if (typeof rawValue === 'object') {
    const entries = Object.entries(rawValue).filter(([, value]) => value !== null && value !== undefined);
    if (entries.length === 0) return [];
    for (const [, value] of entries) assertScalar(value, spec.name);
    if (spec.maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${spec.name}'`);
    }
    if (!spec.explode) {
      const flat = entries.flatMap(([key, value]) => [encodeFn(key), encodeFn(scalarToString(value))]);
      const joined = flat.join(',');
      const piece = opConfig.named ? `${spec.name}=${joined}` : joined;
      return [piece];
    }
    return entries.map(([key, value]) => {
      const ek = encodeFn(key);
      const ev = encodeFn(scalarToString(value));
      if (opConfig.named && ev === '') return `${ek}${opConfig.ifEmpty}`;
      return `${ek}=${ev}`;
    });
  }

  assertScalar(rawValue, spec.name);
  const truncated = truncate(scalarToString(rawValue), spec.maxLength);
  const encoded = encodeFn(truncated);
  if (!opConfig.named) return [encoded];
  return [encoded === '' ? `${spec.name}${opConfig.ifEmpty}` : `${spec.name}=${encoded}`];
}

function expandExpression(expression, variables) {
  const opConfig = OPERATORS[expression.operator];
  const encodeFn = opConfig.literalStyle ? encodeLiteral : encodeUnreserved;
  const allPieces = [];
  for (const spec of expression.variables) {
    const rawValue = Object.prototype.hasOwnProperty.call(variables, spec.name)
      ? variables[spec.name]
      : undefined;
    allPieces.push(...buildPieces(spec, rawValue, opConfig, encodeFn));
  }
  if (allPieces.length === 0) return '';
  return opConfig.prefix + allPieces.join(opConfig.separator);
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  if (typeof variables !== 'object' || variables === null) {
    throw new UriTemplateError('variables must be an object');
  }
  const parts = parse(template);
  let result = '';
  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeLiteral(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }
  return result;
}
"}

