{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t3/cell-f21mw6/src/order.js","content":"/**
 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 */
import { COMMAND_TYPES, allowedTypes } from './machine.js';

/** An order and everything that has been asked of it. */
export class Order {
  #id;

  #state = 'created';

  #items = new Map();

  #paidCents = 0;

  #refundedCents = 0;

  #clockMs;

  #audit = [];

  #shipment = null;

  #deliveredAt = null;

  #results = new Map();

  /**
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   */
  constructor(init) {
    if (typeof init !== 'object' || init === null) throw new TypeError('init must be an object');
    if (typeof init.id !== 'string' || init.id === '') throw new TypeError('init.id must be a non-empty string');
    const createdAt = init.createdAt === undefined ? 0 : init.createdAt;
    if (!Number.isInteger(createdAt) || createdAt < 0) {
      throw new TypeError('init.createdAt must be a non-negative integer');
    }
    this.#id = init.id;
    this.#clockMs = createdAt;
  }

  /** @returns {string} Order identity. */
  get id() {
    return this.#id;
  }

  /** @returns {string} Current state. */
  get state() {
    return this.#state;
  }

  /** @returns {Array<{sku: string, qty: number, unitPriceCents: number}>} Items in ascending sku order. */
  get items() {
    return [...this.#items.keys()].sort().map((sku) => ({ ...this.#items.get(sku) }));
  }

  /** @returns {number} Sum of quantity times unit price over all items. */
  get totalCents() {
    let total = 0;
    for (const item of this.#items.values()) total += item.qty * item.unitPriceCents;
    return total;
  }

  /** @returns {number} Amount captured by a successful payment. */
  get paidCents() {
    return this.#paidCents;
  }

  /** @returns {number} Amount refunded so far. */
  get refundedCents() {
    return this.#refundedCents;
  }

  /** @returns {number} High-water mark of command timestamps. */
  get clockMs() {
    return this.#clockMs;
  }

  /** @returns {object[]} Copy of the audit trail, oldest first. */
  get audit() {
    return this.#audit.map((entry) => ({ ...entry }));
  }

  /** @returns {{carrier: string, tracking: string}|null} Shipment details once shipped. */
  get shipment() {
    return this.#shipment === null ? null : { ...this.#shipment };
  }

  /** @returns {number|null} Timestamp of delivery, once delivered. */
  get deliveredAt() {
    return this.#deliveredAt;
  }

  /** @returns {object} Plain description of the order's visible state. */
  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Validate the fields a command's type requires.
   *
   * @param {object} command Command being applied.
   * @returns {{code: string, message: string}|null} Rejection, or null if the fields are fine.
   */
  #validate(command) {
    const requireString = (field) => {
      if (typeof command[field] !== 'string' || command[field] === '') {
        return { code: 'MISSING_FIELD', message: `${field} is required and must be non-empty` };
      }
      return null;
    };
    const requireAmount = (field, min) => {
      const value = command[field];
      if (!Number.isInteger(value) || value < min) {
        return { code: 'BAD_AMOUNT', message: `${field} must be an integer of at least ${min}` };
      }
      return null;
    };

    switch (command.type) {
      case 'addItem':
        return requireString('sku') || requireAmount('qty', 1) || requireAmount('unitPriceCents', 0);
      case 'removeItem':
        return requireString('sku');
      case 'pay':
        return requireAmount('amountCents', 0);
      case 'ship':
        return requireString('carrier') || requireString('tracking');
      case 'cancel':
        return requireString('reason');
      case 'refund':
        return requireAmount('amountCents', 1);
      default:
        return null;
    }
  }

  /**
   * Check business guards once fields are known to be well formed.
   *
   * @param {object} command Command being applied.
   * @returns {{code: string, message: string}|null} Rejection, or null if the guards pass.
   */
  #guard(command) {
    switch (command.type) {
      case 'addItem':
        if (this.#items.has(command.sku)) {
          return { code: 'DUPLICATE_SKU', message: `sku already present: ${command.sku}` };
        }
        return null;
      case 'removeItem':
        if (!this.#items.has(command.sku)) {
          return { code: 'NO_SUCH_ITEM', message: `no such item: ${command.sku}` };
        }
        return null;
      case 'pay':
        if (this.#items.size === 0) {
          return { code: 'EMPTY_ORDER', message: 'cannot pay for an order with no items' };
        }
        if (command.amountCents !== this.totalCents) {
          return { code: 'AMOUNT_MISMATCH', message: 'payment does not match the order total' };
        }
        return null;
      case 'refund':
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return { code: 'REFUND_TOO_LARGE', message: 'refund exceeds the amount still owed' };
        }
        return null;
      default:
        return null;
    }
  }

  /**
   * Apply the effect of an accepted command and report the resulting state.
   *
   * @param {object} command Command being applied.
   * @returns {string} The state after the effect.
   */
  #effect(command) {
    switch (command.type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        return 'created';
      case 'removeItem':
        this.#items.delete(command.sku);
        return 'created';
      case 'pay':
        this.#paidCents = command.amountCents;
        return 'paid';
      case 'pack':
        return 'packed';
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        return 'shipped';
      case 'deliver':
        this.#deliveredAt = command.at;
        return 'delivered';
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        return 'cancelled';
      case 'refund':
        this.#refundedCents += command.amountCents;
        return this.#refundedCents >= this.#paidCents ? 'refunded' : 'delivered';
      default:
        return this.#state;
    }
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) {
      throw new TypeError(`unknown command type: ${command.type}`);
    }
    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }
    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    const { type, commandId, at } = command;

    if (this.#results.has(commandId)) {
      return { ...this.#results.get(commandId), replayed: true };
    }

    const from = this.#state;
    let entryAt = at;
    let outcome;

    if (at < this.#clockMs) {
      entryAt = this.#clockMs;
      outcome = { code: 'CLOCK_REGRESSION', message: 'command time precedes the order clock' };
    } else {
      this.#clockMs = at;
      if (!allowedTypes(from).includes(type)) {
        outcome = { code: 'BAD_STATE', message: `${type} is not allowed while the order is ${from}` };
      } else {
        outcome = this.#validate(command) || this.#guard(command);
      }
    }

    const seq = this.#audit.length + 1;
    let to = from;
    let result;

    if (outcome) {
      result = { ok: false, code: outcome.code, message: outcome.message, state: from, seq, replayed: false };
    } else {
      to = this.#effect(command);
      this.#state = to;
      result = { ok: true, state: to, seq, replayed: false };
    }

    const entry = { seq, commandId, type, at: entryAt, from, to, ok: result.ok };
    if (!result.ok) entry.code = result.code;
    this.#audit.push(entry);
    this.#results.set(commandId, result);

    return result;
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}
"}

