  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Validate the fields a command's type requires.
   *
   * @param {object} command Command being applied.
   * @returns {{code: string, message: string}|null} Rejection, or null if the fields are fine.
   */
  #validate(command) {
    const requireString = (field) => {
      if (typeof command[field] !== 'string' || command[field] === '') {
        return { code: 'MISSING_FIELD', message: `${field} is required and must be non-empty` };
      }
      return null;
    };
    const requireAmount = (field, min) => {
      const value = command[field];
      if (!Number.isInteger(value) || value < min) {
        return { code: 'BAD_AMOUNT', message: `${field} must be an integer of at least ${min}` };
      }
      return null;
    };

    switch (command.type) {
      case 'addItem':
        return requireString('sku') || requireAmount('qty', 1) || requireAmount('unitPriceCents', 0);
      case 'removeItem':
        return requireString('sku');
      case 'pay':
        return requireAmount('amountCents', 0);
      case 'ship':
        return requireString('carrier') || requireString('tracking');
      case 'cancel':
        return requireString('reason');
      case 'refund':
        return requireAmount('amountCents', 1);
      default:
        return null;
    }
