{"file_path":"src/trie.js","content":"/**
 * Prefix index over Unicode strings.
 *
 * Each node represents a distinct prefix, keyed by Unicode code point so a
 * character outside the basic multilingual plane is a single step and never
 * a pair of surrogate halves. Each node tracks how many stored words live in
 * its subtree, so counting a prefix costs only the length of the prefix.
 */
class TrieNode {
  /** @type {Map<string, TrieNode>} */
  children = new Map();

  /** Number of stored words in this node's subtree, this node included. */
  count = 0;

  /** Whether a word ends exactly at this node. */
  isEnd = false;

  /** @type {unknown} */
  value = undefined;
}

/**
 * Splits a string into an array of single code point strings.
 * @param {string} value String to split.
 * @returns {string[]} Code points, each as a one-character (in code point
 *   terms) string.
 */
function toCodePoints(value) {
  return [...value];
}

/**
 * Validates that a value is a string, throwing with a field-specific message.
 * @param {unknown} value Value to check.
 * @param {string} name Field name to mention in the error message.
 * @returns {void}
 */
function assertString(value, name) {
  if (typeof value !== 'string') {
    throw new TypeError(`${name} must be a string`);
  }
}

/**
 * Validates a search limit.
 * @param {unknown} limit Value to check.
 * @returns {void}
 */
function assertLimit(limit) {
  const ok = limit === Number.POSITIVE_INFINITY || (Number.isSafeInteger(limit) && limit >= 0);
  if (!ok) {
    throw new TypeError('limit must be a non-negative integer');
  }
}

/**
 * Sorts child code point keys of a node by code point value.
 * @param {TrieNode} node Node whose children to order.
 * @returns {string[]} Child keys in code point order.
 */
function sortedChildKeys(node) {
  return [...node.children.keys()].sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
}

export class Trie {
  #root = new TrieNode();

  #size = 0;

  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    assertString(word, 'word');
    const path = [this.#root];
    let node = this.#root;
    for (const char of toCodePoints(word)) {
      let child = node.children.get(char);
      if (!child) {
        child = new TrieNode();
        node.children.set(char, child);
        this.#nodeCount += 1;
      }
      path.push(child);
      node = child;
    }
    const previous = node.isEnd ? node.value : undefined;
    if (!node.isEnd) {
      this.#size += 1;
      for (const n of path) n.count += 1;
    }
    node.isEnd = true;
    node.value = value;
    return previous;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    assertString(word, 'word');
    const node = this.#walk(word);
    return node && node.isEnd ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    assertString(word, 'word');
    const node = this.#walk(word);
    return Boolean(node && node.isEnd);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    assertString(word, 'word');
    const chars = toCodePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const char of chars) {
      const child = node.children.get(char);
      if (!child) return false;
      path.push(child);
      node = child;
    }
    if (!node.isEnd) return false;

    node.isEnd = false;
    node.value = undefined;
    this.#size -= 1;
    for (const n of path) n.count -= 1;

    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.count === 0 && current.children.size === 0) {
        const parent = path[i - 1];
        parent.children.delete(chars[i - 1]);
        this.#nodeCount -= 1;
      } else {
        break;
      }
    }

    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    assertString(prefix, 'prefix');
    const node = this.#walk(prefix);
    return node ? node.count : 0;
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    assertString(prefix, 'prefix');
    assertLimit(limit);
    const node = this.#walk(prefix);
    if (!node) return [];
    const results = [];
    this.#collect(node, prefix, results, limit, false);
    return results.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const results = [];
    this.#collect(this.#root, '', results, Number.POSITIVE_INFINITY, true);
    return results;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    assertString(text, 'text');
    let node = this.#root;
    let best = null;
    if (node.isEnd) best = { word: '', value: node.value };
    let word = '';
    for (const char of toCodePoints(text)) {
      const child = node.children.get(char);
      if (!child) break;
      word += char;
      node = child;
      if (node.isEnd) best = { word, value: node.value };
    }
    return best;
  }

  /**
   * Walks from the root along a string's code points.
   * @param {string} value String to walk.
   * @returns {TrieNode | null} Reached node, or null when the path is absent.
   */
  #walk(value) {
    let node = this.#root;
    for (const char of toCodePoints(value)) {
      const child = node.children.get(char);
      if (!child) return null;
      node = child;
    }
    return node;
  }

  /**
   * Depth-first collects word/value pairs under a node, in code point order.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Accumulated word text down to this node.
   * @param {Array<[string, unknown]>} results Output accumulator.
   * @param {number} limit Maximum number of results to collect.
   * @param {boolean} withValues Unused flag kept for clarity of call sites.
   * @returns {boolean} True once the limit has been reached.
   */
  #collect(node, prefix, results, limit, withValues) {
    if (results.length >= limit) return true;
    if (node.isEnd) {
      results.push([prefix, node.value]);
      if (results.length >= limit) return true;
    }
    for (const key of sortedChildKeys(node)) {
      const child = node.children.get(key);
      if (this.#collect(child, prefix + key, results, limit, withValues)) return true;
    }
    return false;
  }
}
"}

