/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const OPERATOR_CHARS = new Set(['+', '-', '*', '/', '%', '^']);
const NAME_START = /[A-Za-z_]/;
const NAME_PART = /[A-Za-z0-9_]/;
const DIGIT = /[0-9]/;

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  let i = 0;
  const len = input.length;

  while (i < len) {
    const ch = input[i];

    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f') {
      i += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen', value: '(', index: i });
      i += 1;
      continue;
    }
    if (ch === ')') {
      tokens.push({ type: 'rparen', value: ')', index: i });
      i += 1;
      continue;
    }
    if (ch === ',') {
      tokens.push({ type: 'comma', value: ',', index: i });
      i += 1;
      continue;
    }
    if (OPERATOR_CHARS.has(ch)) {
      tokens.push({ type: 'operator', value: ch, index: i });
      i += 1;
      continue;
    }

    if (DIGIT.test(ch) || (ch === '.' && DIGIT.test(input[i + 1] || ''))) {
      const start = i;
      let j = i;
      let sawDigits = false;

      while (j < len && DIGIT.test(input[j])) {
        j += 1;
        sawDigits = true;
      }
      if (input[j] === '.') {
        j += 1;
        let fracDigits = false;
        while (j < len && DIGIT.test(input[j])) {
          j += 1;
          fracDigits = true;
        }
        if (!fracDigits) throw new ExprError(`malformed number at ${start}`, start);
        sawDigits = true;
      }
      if (input[j] === 'e' || input[j] === 'E') {
        j += 1;
        if (input[j] === '+' || input[j] === '-') j += 1;
        let expDigits = false;
        while (j < len && DIGIT.test(input[j])) {
          j += 1;
          expDigits = true;
        }
        if (!expDigits) throw new ExprError(`malformed number at ${start}`, start);
      }

      // Check that nothing which looks like it continues a number/identifier follows improperly,
      // e.g. "2abc" or "1.2.3"
      if (j < len && (NAME_START.test(input[j]) || input[j] === '.')) {
        throw new ExprError(`malformed number at ${start}`, start);
      }

      const text = input.slice(start, j);
      const value = Number(text);
      tokens.push({ type: 'number', value, index: start });
      i = j;
      continue;
    }

    if (NAME_START.test(ch)) {
      const start = i;
      let j = i;
      while (j < len && NAME_PART.test(input[j])) j += 1;
      tokens.push({ type: 'name', value: input.slice(start, j), index: start });
      i = j;
      continue;
    }

    // Unexpected character: quote the whole code point.
    const codePoint = input.codePointAt(i);
    const char = String.fromCodePoint(codePoint);
    throw new ExprError(`unexpected character '${char}' at ${i}`, i);
  }

  return tokens;
}
"}

