import { ExprError, tokenize } from './tokenize.js';

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  function peek() {
    return tokens[pos];
  }

  function parsePrimary() {
    const token = tokens[pos];
    if (!token) throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    pos += 1;

    if (token.type === 'number') {
      return { type: 'number', value: token.value, index: token.index };
    }

    if (token.type === 'name') {
      const next = tokens[pos];
      if (next && next.type === 'lparen') {
        pos += 1; // consume '('
        const args = [];
        const first = tokens[pos];
        if (!(first && first.type === 'rparen')) {
          args.push(parseExpr());
          while (tokens[pos] && tokens[pos].type === 'comma') {
            pos += 1;
            args.push(parseExpr());
          }
        }
        const closing = tokens[pos];
        if (!closing) throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
        if (closing.type !== 'rparen') {
          throw new ExprError(`unexpected token '${closing.value}' at ${closing.index}`, closing.index);
        }
        pos += 1; // consume ')'
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }

    if (token.type === 'lparen') {
      const inner = parseExpr();
      const closing = tokens[pos];
      if (!closing || closing.type !== 'rparen') {
        const index = closing ? closing.index : input.length;
        throw new ExprError(`missing closing parenthesis at ${index}`, index);
      }
      pos += 1; // consume ')'
      return inner;
    }

    throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
  }

  function parsePower() {
    const left = parsePrimary();
    const token = peek();
    if (token && token.type === 'operator' && token.value === '^') {
      pos += 1;
      const right = parseUnary();
      return { type: 'binary', op: '^', left, right, index: token.index };
    }
    return left;
  }

  function parseUnary() {
    const token = peek();
    if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      pos += 1;
      const operand = parseUnary();
      return { type: 'unary', op: token.value, operand, index: token.index };
    }
    return parsePower();
  }

  function parseTerm() {
    let left = parseUnary();
    for (;;) {
      const token = peek();
      if (token && token.type === 'operator' && (token.value === '*' || token.value === '/' || token.value === '%')) {
        pos += 1;
        const right = parseUnary();
        left = { type: 'binary', op: token.value, left, right, index: token.index };
      } else {
        break;
      }
    }
    return left;
  }

  function parseExpr() {
    let left = parseTerm();
    for (;;) {
      const token = peek();
      if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
        pos += 1;
        const right = parseTerm();
        left = { type: 'binary', op: token.value, left, right, index: token.index };
      } else {
        break;
      }
    }
    return left;
  }

  const tree = parseExpr();
  if (pos < tokens.length) {
    const token = tokens[pos];
    throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
  }
  return tree;
}
"}

