{"file_path":"src/index.js","content":"/**
 * Arithmetic expression evaluator: tokeniser, precedence-climbing parser and a
 * tree walker with named constants, variables and a fixed function table.
 */

import { ExprError, tokenize } from './tokenize.js';
import { parse } from './parse.js';

export { ExprError, tokenize, parse };

const CONSTANTS = { pi: Math.PI, e: Math.E };

const FUNCTIONS = {
  abs: { min: 1, max: 1, fn: (a) => Math.abs(a) },
  sqrt: { min: 1, max: 1, fn: (a) => Math.sqrt(a) },
  floor: { min: 1, max: 1, fn: (a) => Math.floor(a) },
  ceil: { min: 1, max: 1, fn: (a) => Math.ceil(a) },
  round: { min: 1, max: 1, fn: (a) => Math.round(a) },
  sign: { min: 1, max: 1, fn: (a) => Math.sign(a) },
  pow: { min: 2, max: 2, fn: (a, b) => a ** b },
  atan2: { min: 2, max: 2, fn: (a, b) => Math.atan2(a, b) },
  min: { min: 1, max: Infinity, fn: (...args) => Math.min(...args) },
  max: { min: 1, max: Infinity, fn: (...args) => Math.max(...args) },
};

function checkFinite(value, index) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new ExprError(`non-finite result at ${index}`, index);
  }
  return value;
}

function evalNode(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;
    case 'variable': {
      if (Object.prototype.hasOwnProperty.call(env, node.name)) {
        const value = env[node.name];
        if (typeof value !== 'number' || !Number.isFinite(value)) {
          throw new ExprError(`variable ${node.name} is not a finite number at ${node.index}`, node.index);
        }
        return value;
      }
      if (Object.prototype.hasOwnProperty.call(CONSTANTS, node.name)) {
        return CONSTANTS[node.name];
      }
      throw new ExprError(`unknown variable: ${node.name} at ${node.index}`, node.index);
    }
    case 'unary': {
      const operand = evalNode(node.operand, env);
      const value = node.op === '-' ? -operand : +operand;
      return checkFinite(value, node.index);
    }
    case 'binary': {
      const left = evalNode(node.left, env);
      const right = evalNode(node.right, env);
      if ((node.op === '/' || node.op === '%') && right === 0) {
        throw new ExprError(`division by zero at ${node.index}`, node.index);
      }
      let value;
      switch (node.op) {
        case '+':
          value = left + right;
          break;
        case '-':
          value = left - right;
          break;
        case '*':
          value = left * right;
          break;
        case '/':
          value = left / right;
          break;
        case '%':
          value = left % right;
          break;
        case '^':
          value = left ** right;
          break;
        default:
          throw new Error(`unknown operator: ${node.op}`);
      }
      return checkFinite(value, node.index);
    }
    case 'call': {
      const def = FUNCTIONS[node.name];
      if (!def) throw new ExprError(`unknown function: ${node.name} at ${node.index}`, node.index);
      const args = node.args.map((arg) => evalNode(arg, env));
      if (args.length < def.min || args.length > def.max) {
        if (def.min === def.max) {
          const word = def.min === 1 ? 'argument' : 'arguments';
          throw new ExprError(
            `function ${node.name} expects ${def.min} ${word}, got ${args.length} at ${node.index}`,
            node.index,
          );
        }
        throw new ExprError(
          `function ${node.name} expects at least ${def.min} argument, got ${args.length} at ${node.index}`,
          node.index,
        );
      }
      const value = def.fn(...args);
      return checkFinite(value, node.index);
    }
    default:
      throw new Error(`unknown node type: ${node.type}`);
  }
}

/**
 * Evaluate an expression.
 *
 * @param {string} input expression source
 * @param {Record<string, number>} [env] variable bindings, shadowing the built-in constants
 * @returns {number} the finite result
 */
export function evaluate(input, env = {}) {
  const tree = parse(input);
  return evalNode(tree, env);
}
"}

