class TrieNode {
  constructor() {
    /** @type {Map<number, TrieNode>} Children indexed by code point */
    this.children = new Map();
    /** @type {unknown} Value stored at this node, if any */
    this.value = undefined;
    /** @type {boolean} True if this node represents a stored word */
    this.isWord = false;
    /** @type {number} Count of words in the subtree rooted here */
    this.wordCount = 0;
  }
}

export class Trie {
  #root = new TrieNode();
  #size = 0;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#countNodes(this.#root);
  }

  #countNodes(node) {
    let count = 1; // count this node
    for (const child of node.children.values()) {
      count += this.#countNodes(child);
    }
    return count;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    if (typeof word !== 'string') {
      throw new TypeError('word must be a string');
    }

    const codePoints = [...word]; // Use spread to split by code point, not UTF-16 units
    let node = this.#root;

    // Traverse/create the path
    for (const char of codePoints) {
      const cp = char.codePointAt(0);
      if (!node.children.has(cp)) {
        node.children.set(cp, new TrieNode());
      }
      node = node.children.get(cp);
    }

    const previous = node.isWord ? node.value : undefined;

    // If this is a new word, increment counts along the path
    if (!node.isWord) {
      this.#size += 1;
      let current = this.#root;
      for (const char of codePoints) {
        const cp = char.codePointAt(0);
        current = current.children.get(cp);
        current.wordCount += 1;
      }
    }

    node.isWord = true;
    node.value = value;

    return previous;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    if (typeof word !== 'string') {
      throw new TypeError('word must be a string');
    }

    const node = this.#findNode(word);
    return node && node.isWord ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    if (typeof word !== 'string') {
      throw new TypeError('word must be a string');
    }

    const node = this.#findNode(word);
    return node ? node.isWord : false;
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    if (typeof word !== 'string') {
      throw new TypeError('word must be a string');
    }

    const codePoints = [...word];
    const node = this.#findNode(word);

    if (!node || !node.isWord) {
      return false;
    }

    // Mark as not a word and clear its value
    node.isWord = false;
    node.value = undefined;
    this.#size -= 1;

    // Decrement word counts along the path
    let current = this.#root;
    for (const char of codePoints) {
      const cp = char.codePointAt(0);
      current = current.children.get(cp);
      current.wordCount -= 1;
    }

    // Clean up empty nodes from the leaf back to root
    this.#cleanupNodes(word);

    return true;
  }

  #cleanupNodes(word) {
    const codePoints = [...word];
    const path = [];
    let node = this.#root;

    // Build the path to the end node
    for (const char of codePoints) {
      const cp = char.codePointAt(0);
      path.push([node, cp]);
      node = node.children.get(cp);
    }

    // Walk backwards removing empty nodes
    for (let i = path.length - 1; i >= 0; i -= 1) {
      const [parent, cp] = path[i];
      const child = parent.children.get(cp);

      // Remove node if it has no children and is not a word endpoint
      if (child.children.size === 0 && !child.isWord) {
        parent.children.delete(cp);
      } else {
        // Stop cleanup when we hit a node that should stay
        break;
      }
    }
  }

  #findNode(word) {
    const codePoints = [...word];
    let node = this.#root;

    for (const char of codePoints) {
      const cp = char.codePointAt(0);
      if (!node.children.has(cp)) {
        return null;
      }
      node = node.children.get(cp);
    }

    return node;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    if (typeof prefix !== 'string') {
      throw new TypeError('prefix must be a string');
    }

    const node = this.#findNode(prefix);
    return node ? node.wordCount : 0;
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    if (typeof prefix !== 'string') {
      throw new TypeError('prefix must be a string');
    }

    if (limit !== Number.POSITIVE_INFINITY) {
      if (!Number.isSafeInteger(limit) || limit < 0) {
        throw new TypeError('limit must be a non-negative integer');
      }
    }

    const node = this.#findNode(prefix);
    if (!node) {
      return [];
    }

    const results = [];
    this.#collectWords(node, prefix, results, limit);
    return results;
  }

  #collectWords(node, currentWord, results, limit) {
    if (results.length >= limit) {
      return;
    }

    if (node.isWord) {
      results.push(currentWord);
      if (results.length >= limit) {
        return;
      }
    }

    // Get children in code point order
    const codePoints = Array.from(node.children.keys()).sort((a, b) => a - b);
    for (const cp of codePoints) {
      if (results.length >= limit) {
        return;
      }
      const child = node.children.get(cp);
      const char = String.fromCodePoint(cp);
      this.#collectWords(child, currentWord + char, results, limit);
    }
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const results = [];
    this.#collectEntries(this.#root, '', results);
    return results;
  }

  #collectEntries(node, currentWord, results) {
    if (node.isWord) {
      results.push([currentWord, node.value]);
    }

    // Get children in code point order
    const codePoints = Array.from(node.children.keys()).sort((a, b) => a - b);
    for (const cp of codePoints) {
      const child = node.children.get(cp);
      const char = String.fromCodePoint(cp);
      this.#collectEntries(child, currentWord + char, results);
    }
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    if (typeof text !== 'string') {
      throw new TypeError('text must be a string');
    }

    const codePoints = [...text];
    let node = this.#root;
    let lastMatch = null;
    let currentWord = '';

    for (const char of codePoints) {
      const cp = char.codePointAt(0);
      if (!node.children.has(cp)) {
        break;
      }
      node = node.children.get(cp);
      currentWord += char;

      if (node.isWord) {
        lastMatch = { word: currentWord, value: node.value };
      }
    }

    return lastMatch;
  }
}
