}","new_string":"  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
    if (!isNonEmptyString(command.commandId)) throw new TypeError('command must carry a non-empty commandId');
    if (!isValidInt(command.at, 0)) throw new TypeError('command must carry a non-negative integer at');

    if (this.#results.has(command.commandId)) {
      return { ...this.#results.get(command.commandId), replayed: true };
    }

    const { type, at } = command;
    const from = this.#state;

    if (at < this.#clockMs) {
      const entryAt = this.#clockMs;
      const outcome = fail('CLOCK_REGRESSION', 'command timestamp is earlier than the order clock');
      const result = { ok: false, code: outcome.code, message: outcome.message, state: from };
      this.#recordAndStore(command, entryAt, from, from, result);
      return { ...result, replayed: false };
    }

    this.#clockMs = at;

    if (!allowedTypes(from).includes(type)) {
      const outcome = fail('BAD_STATE', `${type} is not allowed while the order is ${from}`);
      const result = { ok: false, code: outcome.code, message: outcome.message, state: from };
      this.#recordAndStore(command, at, from, from, result);
      return { ...result, replayed: false };
    }

    const fieldFailure = this.#validateFields(type, command);
    if (fieldFailure) {
      const result = { ok: false, code: fieldFailure.code, message: fieldFailure.message, state: from };
      this.#recordAndStore(command, at, from, from, result);
      return { ...result, replayed: false };
    }

    const guardFailure = this.#validateBusiness(type, command);
    if (guardFailure) {
      const result = { ok: false, code: guardFailure.code, message: guardFailure.message, state: from };
      this.#recordAndStore(command, at, from, from, result);
      return { ...result, replayed: false };
    }

    const to = this.#applyEffect(type, command);
    const result = { ok: true, state: to };
    this.#recordAndStore(command, at, from, to, result);
    return { ...result, replayed: false };
  }

  #recordAndStore(command, at, from, to, result) {
    const entry = {
      seq: this.#audit.length + 1,
      commandId: command.commandId,
      type: command.type,
      at,
      from,
      to,
      ok: result.ok,
    };
    if (!result.ok) entry.code = result.code;
    this.#audit.push(entry);
    const stored = { ...result, seq: entry.seq };
    this.#results.set(command.commandId, stored);
    Object.assign(result, { seq: entry.seq });
  }

  #validateFields(type, command) {
    if (type === 'addItem' || type === 'removeItem') {
      if (!isNonEmptyString(command.sku)) return fail('MISSING_FIELD', 'sku is required');
    }
    if (type === 'ship') {
      if (!isNonEmptyString(command.carrier)) return fail('MISSING_FIELD', 'carrier is required');
      if (!isNonEmptyString(command.tracking)) return fail('MISSING_FIELD', 'tracking is required');
    }
    if (type === 'cancel') {
      if (!isNonEmptyString(command.reason)) return fail('MISSING_FIELD', 'reason is required');
    }
    if (type === 'addItem') {
      if (!isValidInt(command.qty, 1)) return fail('BAD_AMOUNT', 'qty must be an integer of at least 1');
      if (!isValidInt(command.unitPriceCents, 0)) {
        return fail('BAD_AMOUNT', 'unitPriceCents must be a non-negative integer');
      }
    }
    if (type === 'pay') {
      if (!isValidInt(command.amountCents, 0)) return fail('BAD_AMOUNT', 'amountCents must be a non-negative integer');
    }
    if (type === 'refund') {
      if (!isValidInt(command.amountCents, 1)) return fail('BAD_AMOUNT', 'amountCents must be an integer of at least 1');
    }
    return null;
  }

  #validateBusiness(type, command) {
    if (type === 'addItem' && this.#items.has(command.sku)) {
      return fail('DUPLICATE_SKU', `sku ${command.sku} is already on the order`);
    }
    if (type === 'removeItem' && !this.#items.has(command.sku)) {
      return fail('NO_SUCH_ITEM', `sku ${command.sku} is not on the order`);
    }
    if (type === 'pay') {
      if (this.#items.size === 0) return fail('EMPTY_ORDER', 'an order with no items cannot be paid');
      if (command.amountCents !== this.totalCents) {
        return fail('AMOUNT_MISMATCH', `expected ${this.totalCents} but received ${command.amountCents}`);
      }
    }
    if (type === 'refund') {
      const remaining = this.#paidCents - this.#refundedCents;
      if (command.amountCents > remaining) {
        return fail('REFUND_TOO_LARGE', `at most ${remaining} can still be refunded`);
      }
    }
    return null;
  }

  #applyEffect(type, command) {
    switch (type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        return 'created';
      case 'removeItem':
        this.#items.delete(command.sku);
        return 'created';
      case 'pay':
        this.#paidCents = command.amountCents;
        return 'paid';
      case 'pack':
        return 'packed';
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        return 'shipped';
      case 'deliver':
        this.#deliveredAt = command.at;
        return 'delivered';
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        return 'cancelled';
      case 'refund':
        this.#refundedCents += command.amountCents;
        return this.#refundedCents >= this.#paidCents ? 'refunded' : this.#state;
      default:
        throw new TypeError(`unknown command type: ${type}`);
    }
  }

  /**
   * Build an order by applying a command list in order.
   *
