          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        return 'created';
      case 'removeItem':
        this.#items.delete(command.sku);
        return 'created';
      case 'pay':
        this.#paidCents = command.amountCents;
        return 'paid';
      case 'pack':
        return 'packed';
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        return 'shipped';
      case 'deliver':
        this.#deliveredAt = command.at;
        return 'delivered';
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        return 'cancelled';
      case 'refund':
        this.#refundedCents += command.amountCents;
        return this.#refundedCents >= this.#paidCents ? 'refunded' : this.#state;
