{"file_path":"src/kruskal.js","content":"/**
 * Spanning-forest and what-if queries built on the rollback-capable
 * disjoint-set structure.
 *
 * An edge is `[u, v, weight]` with element indices and a finite weight.
 */

import { DisjointSets } from './dsu.js';

/**
 * Validates that a value is a non-negative safe integer count.
 * @param {unknown} count Candidate count.
 * @returns {number} The validated count.
 */
function validateCount(count) {
  if (typeof count !== 'number' || !Number.isSafeInteger(count) || count < 0) {
    throw new TypeError('count must be a non-negative integer');
  }
  return count;
}

/**
 * Validates that a value is an element index in `0 .. count - 1`.
 * @param {unknown} element Candidate element.
 * @param {number} count Element count.
 * @returns {number} The validated element.
 */
function validateElement(element, count) {
  if (
    typeof element !== 'number' ||
    !Number.isSafeInteger(element) ||
    element < 0 ||
    element >= count
  ) {
    throw new RangeError(`element out of range: ${element}`);
  }
  return element;
}

/**
 * Validates and normalizes an edge list.
 * @param {unknown} edges Candidate edge list.
 * @param {number} count Element count.
 * @returns {Array<[number, number, number]>} Validated edges.
 */
function validateEdges(edges, count) {
  if (!Array.isArray(edges)) throw new TypeError('edges must be an array');
  return edges.map((edge) => {
    if (!Array.isArray(edge) || edge.length !== 3) {
      throw new TypeError('edge must be [u, v, weight]');
    }
    const [u, v, weight] = edge;
    validateElement(u, count);
    validateElement(v, count);
    if (typeof weight !== 'number' || !Number.isFinite(weight)) {
      throw new TypeError('weight must be a finite number');
    }
    return [u, v, weight];
  });
}

/**
 * Sorts edges by weight, breaking ties by first endpoint and then second.
 * @param {Array<[number, number, number]>} edges Edges to sort.
 * @returns {Array<[number, number, number]>} Sorted edges.
 */
function sortedEdges(edges) {
  return [...edges].sort((a, b) => a[2] - b[2] || a[0] - b[0] || a[1] - b[1]);
}

/**
 * Applies a sorted edge list to a disjoint-set structure with Kruskal's
 * algorithm, keeping edges that join two different sets.
 * @param {DisjointSets} sets Structure to mutate.
 * @param {Array<[number, number, number]>} edges Edges in weight order.
 * @returns {{edges: Array<[number, number, number]>, weight: number}} Chosen edges and their total weight.
 */
function applyKruskal(sets, edges) {
  const chosen = [];
  let weight = 0;
  for (const edge of edges) {
    const [u, v, w] = edge;
    if (sets.union(u, v)) {
      chosen.push(edge);
      weight += w;
    }
  }
  return { edges: chosen, weight };
}

/**
 * Builds a minimum spanning forest with Kruskal's algorithm, taking edges by
 * weight and breaking ties by the first endpoint and then the second.
 * @param {number} count Element count.
 * @param {unknown} edges Available edges.
 * @returns {{edges: Array<[number, number, number]>, weight: number, components: number}} Chosen edges, their total weight, and the remaining component count.
 */
export function minimumSpanningForest(count, edges) {
  validateCount(count);
  const validated = validateEdges(edges, count);
  const sets = new DisjointSets(count);
  const { edges: chosen, weight } = applyKruskal(sets, sortedEdges(validated));
  return { edges: chosen, weight, components: sets.components };
}

/**
 * Measures how many components remain after each alternative edge set is
 * added on top of a shared base, evaluating each alternative independently by
 * rolling back to the state the base left behind.
 * @param {number} count Element count.
 * @param {unknown} baseEdges Edges applied once, before any alternative.
 * @param {unknown} alternatives Array of edge lists to try one at a time.
 * @returns {{base: number, alternatives: number[]}} Component count for the base and for each alternative.
 */
export function componentsWithAlternatives(count, baseEdges, alternatives) {
  validateCount(count);
  const validatedBase = validateEdges(baseEdges, count);
  if (!Array.isArray(alternatives)) throw new TypeError('alternatives must be an array');
  const validatedAlternatives = alternatives.map((alt) => validateEdges(alt, count));

  const sets = new DisjointSets(count);
  applyKruskal(sets, sortedEdges(validatedBase));
  const base = sets.components;
  const checkpoint = sets.checkpoint();

  const results = [];
  for (const alt of validatedAlternatives) {
    applyKruskal(sets, sortedEdges(alt));
    results.push(sets.components);
    sets.rollback(checkpoint);
  }

  return { base, alternatives: results };
}
"}

