   * Swaps two positions in the backing array and updates the index.
   * @param {number} i First index.
   * @param {number} j Second index.
   * @returns {void}
   */
  #swap(i, j) {
    const items = this.#items;
    [items[i], items[j]] = [items[j], items[i]];
    this.#pos.set(items[i].key, i);
    this.#pos.set(items[j].key, j);
  }

  /**
   * Moves the entry at an index up until the heap property holds.
   * @param {number} index Starting index.
   * @returns {void}
   */
  #siftUp(index) {
    const items = this.#items;
    let i = index;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.#compare(items[i], items[parent]) < 0) {
        this.#swap(i, parent);
        i = parent;
      } else break;
    }
  }

  /**
   * Moves the entry at an index down until the heap property holds.
   * @param {number} index Starting index.
   * @returns {void}
   */
  #siftDown(index) {
    const items = this.#items;
    const n = items.length;
    let i = index;
    for (;;) {
      const left = 2 * i + 1;
      const right = 2 * i + 2;
      let smallest = i;
      if (left < n && this.#compare(items[left], items[smallest]) < 0) smallest = left;
      if (right < n && this.#compare(items[right], items[smallest]) < 0) smallest = right;
      if (smallest === i) break;
      this.#swap(i, smallest);
      i = smallest;
    }
  }

