 * Binary min-heap with an index from key to position.
 *
 * Entries are ordered primarily by priority, then by insertion order among
 * equal priorities. The `#pos` map tracks each key's current index in the
 * backing array so keyed operations (`decreaseKey`, `setPriority`, `remove`)
 * run in O(log n), while lookups (`has`, `priorityOf`) are O(1).
 */
export class IndexedHeap {
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} */
  #pos = new Map();

  /** @type {number} */
  #seq = 0;

  /** @returns {number} Number of entries currently held. */
  get size() {
    return this.#items.length;
  }

  /**
   * Validates a key.
   * @param {unknown} key Candidate key.
   * @returns {void}
   */
  #checkKey(key) {
    if (typeof key !== 'string') throw new TypeError('key must be a string');
  }

  /**
   * Validates a priority.
   * @param {unknown} priority Candidate priority.
   * @returns {void}
   */
  #checkPriority(priority) {
    if (typeof priority !== 'number' || !Number.isFinite(priority)) {
      throw new TypeError('priority must be a finite number');
    }
  }

  /**
   * Compares two entries by priority, then by insertion order.
   * @param {{priority: number, seq: number}} a First entry.
   * @param {{priority: number, seq: number}} b Second entry.
   * @returns {number} Negative when a leaves first.
   */
  #compare(a, b) {
    return a.priority - b.priority || a.seq - b.seq;
  }

  /**
   * Swaps two positions in the backing array and updates the index.
   * @param {number} i First index.
   * @param {number} j Second index.
   * @returns {void}
   */
  #swap(i, j) {
    const items = this.#items;
    [items[i], items[j]] = [items[j], items[i]];
    this.#pos.set(items[i].key, i);
    this.#pos.set(items[j].key, j);
  }

  /**
   * Moves the entry at an index up until the heap property holds.
   * @param {number} index Starting index.
   * @returns {void}
   */
  #siftUp(index) {
    const items = this.#items;
    let i = index;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.#compare(items[i], items[parent]) < 0) {
        this.#swap(i, parent);
        i = parent;
      } else break;
    }
  }

  /**
   * Moves the entry at an index down until the heap property holds.
   * @param {number} index Starting index.
   * @returns {void}
   */
  #siftDown(index) {
    const items = this.#items;
    const n = items.length;
    let i = index;
    for (;;) {
      const left = 2 * i + 1;
      const right = 2 * i + 2;
      let smallest = i;
      if (left < n && this.#compare(items[left], items[smallest]) < 0) smallest = left;
      if (right < n && this.#compare(items[right], items[smallest]) < 0) smallest = right;
      if (smallest === i) break;
      this.#swap(i, smallest);
      i = smallest;
    }
  }

  /**
   * Adds an entry.
   * @param {string} key Unique key.
   * @param {number} priority Ordering priority; smaller leaves first.
   * @returns {void}
   */
