    this.#checkKey(key);
    this.#checkPriority(priority);
    if (this.#pos.has(key)) throw new Error(`duplicate key: "${key}"`);
    const item = { key, priority, seq: this.#seq };
    this.#seq += 1;
    const index = this.#items.length;
    this.#items.push(item);
    this.#pos.set(key, index);
    this.#siftUp(index);
  }

  /**
   * Reads the next entry without removing it.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  peek() {
    if (this.#items.length === 0) return undefined;
    const { key, priority } = this.#items[0];
    return { key, priority };
  }

  /**
   * Removes and returns the next entry.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  pop() {
    if (this.#items.length === 0) return undefined;
    const top = this.#items[0];
    const last = this.#items.length - 1;
    if (last === 0) {
      this.#items.pop();
      this.#pos.delete(top.key);
    } else {
      this.#swap(0, last);
      this.#items.pop();
      this.#pos.delete(top.key);
      this.#siftDown(0);
    }
    return { key: top.key, priority: top.priority };
  }

  /**
   * Reports whether a key is held.
   * @param {string} key Key to look up.
   * @returns {boolean} True when the key is held.
   */
  has(key) {
    this.#checkKey(key);
    return this.#pos.has(key);
  }

  /**
   * Reads the priority stored for a key.
   * @param {string} key Key to look up.
   * @returns {number | undefined} Stored priority, or undefined when absent.
   */
  priorityOf(key) {
    this.#checkKey(key);
    const index = this.#pos.get(key);
    return index === undefined ? undefined : this.#items[index].priority;
  }

  /**
   * Lowers the priority of a held key.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority; must not exceed the current one.
   * @returns {void}
   */
  decreaseKey(key, priority) {
    this.#checkKey(key);
    this.#checkPriority(priority);
    const index = this.#pos.get(key);
    if (index === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    const current = this.#items[index].priority;
    if (priority > current) throw new RangeError(`priority must not increase for "${key}"`);
    this.#items[index].priority = priority;
    this.#siftUp(index);
  }

  /**
   * Sets the priority of a held key in either direction.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority.
   * @returns {void}
   */
  setPriority(key, priority) {
    this.#checkKey(key);
    this.#checkPriority(priority);
    const index = this.#pos.get(key);
    if (index === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    const current = this.#items[index].priority;
    this.#items[index].priority = priority;
    if (priority < current) this.#siftUp(index);
    else if (priority > current) this.#siftDown(index);
  }

  /**
   * Removes a held key.
   * @param {string} key Key to remove.
   * @returns {boolean} True when an entry was removed.
   */
  remove(key) {
    this.#checkKey(key);
    const index = this.#pos.get(key);
    if (index === undefined) return false;
    const last = this.#items.length - 1;
    if (index === last) {
      this.#items.pop();
      this.#pos.delete(key);
    } else {
      this.#swap(index, last);
      this.#items.pop();
      this.#pos.delete(key);
      this.#siftDown(index);
      this.#siftUp(index);
    }
    return true;
  }

  /**
   * Empties the heap.
   * @returns {Array<{key: string, priority: number}>} Every entry in pop order.
   */
  drain() {
    const result = [];
    let next = this.pop();
    while (next !== undefined) {
      result.push(next);
      next = this.pop();
    }
    return result;
  }
}
