{"file_path":"src/trie.js","content":"/**
 * Prefix index over Unicode strings.
 *
 * Builds a real trie with one node per distinct prefix, walked by Unicode
 * code point so characters outside the basic plane are single steps.
 * Every listing is ordered by code point.
 */

/**
 * A single node in the trie.
 * @private
 */
class TrieNode {
  constructor() {
    /** @type {Map<number, TrieNode>} Map from code point to child node */
    this.children = new Map();

    /** @type {unknown} The value stored at this node, if any */
    this.value = undefined;

    /** @type {boolean} Whether this node represents a stored word */
    this.hasValue = false;

    /** @type {number} Count of stored words in this subtree */
    this.count = 0;
  }
}

export class Trie {
  /** @type {TrieNode} */
  #root = new TrieNode();

  /** @type {number} */
  #size = 0;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#countNodes(this.#root);
  }

  /**
   * Counts nodes in subtree rooted at node.
   * @param {TrieNode} node
   * @returns {number}
   * @private
   */
  #countNodes(node) {
    let count = 1; // count this node
    for (const child of node.children.values()) {
      count += this.#countNodes(child);
    }
    return count;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');

    // Walk/create path through trie
    const chars = [...word]; // Split by Unicode code points
    let node = this.#root;

    for (const char of chars) {
      const codePoint = char.codePointAt(0);
      if (!node.children.has(codePoint)) {
        node.children.set(codePoint, new TrieNode());
      }
      node = node.children.get(codePoint);
    }

    // Store the previous value
    const previous = node.hasValue ? node.value : undefined;
    const isNew = !node.hasValue;

    // Set the value
    node.value = value;
    if (isNew) {
      node.hasValue = true;
      this.#size++;

      // Increment counts from root to this node
      let current = this.#root;
      current.count++;
      for (const char of chars) {
        const codePoint = char.codePointAt(0);
        current = current.children.get(codePoint);
        current.count++;
      }
    }

    return previous;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#findNode(word);
    return node && node.hasValue ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#findNode(word);
    return node ? node.hasValue : false;
  }

  /**
   * Finds the node for a word, or null if the path doesn't exist.
   * @param {string} word
   * @returns {TrieNode | null}
   * @private
   */
  #findNode(word) {
    const chars = [...word];
    let node = this.#root;
    for (const char of chars) {
      const codePoint = char.codePointAt(0);
      if (!node.children.has(codePoint)) return null;
      node = node.children.get(codePoint);
    }
    return node;
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');

    const chars = [...word];
    let node = this.#root;
    const path = [this.#root];

    // Walk to the node for this word
    for (const char of chars) {
      const codePoint = char.codePointAt(0);
      if (!node.children.has(codePoint)) return false;
      node = node.children.get(codePoint);
      path.push(node);
    }

    // Check if this word exists
    if (!node.hasValue) return false;

    // Mark the node as not containing a value
    node.hasValue = false;
    node.value = undefined;
    this.#size--;

    // Decrement counts along the path
    for (const n of path) {
      n.count--;
    }

    // Remove nodes that are no longer needed (no value, no children)
    for (let i = path.length - 1; i > 0; i--) {
