   */
  undo() {
    if (this.#history.length === 0) return false;
    const entry = this.#history.pop();
    const { root, attached, rootSize } = entry;

    // Get the attached node's original size by subtracting from current root size
    const attachedSize = this.#size[root] - rootSize;

    // Restore the state
    this.#parent[attached] = attached;
    this.#size[root] = rootSize;
    this.#size[attached] = attachedSize;
    this.#components += 1;
    this.#unions -= 1;

    return true;
  }

