  if (!Array.isArray(edges)) {
    throw new TypeError('edges must be an array');
  }
}

/**
 * Validates a single edge.
 * @param {unknown} edge 
 * @param {number} count 
 */
function validateEdge(edge, count) {
  if (!Array.isArray(edge) || edge.length !== 3) {
    throw new TypeError('edge must be [u, v, weight]');
  }
  const [u, v, weight] = edge;
  if (!Number.isFinite(weight)) {
    throw new TypeError('weight must be a finite number');
  }
  validateElement(u, count);
  validateElement(v, count);
}

